"""Spelling-based Russian inflection detector, strongest on adjective endings.

Gender/number/case fragments such as -ная and -ные receive large negative
values. Adjective-forming suffixes, determiners and whole words get scaled
responses; noun and verb endings are weaker. This is not a grammar parser.
One previous token handles participial endings split after -анны/-енны.
Most non-Russian tokens are left at zero, including their smaller responses.
"""
READS = ()

# Each pair is (bare ending, ending with an adjective-forming n).
ADJECTIVE_CASES = {
    'ый': (-4.6, -5.2),
    'ий': (-1.9, -2.4),
    'ая': (-4.9, -6.6),
    'яя': (-3.7, -3.7),
    'ое': (-5.3, -6.4),
    'ее': (-3.3, -2.5),
    'ые': (-6.6, -6.7),
    'ие': (-3.2, -3.0),
    'ого': (-2.7, -3.9),
    'его': (-2.5, -2.6),
    'ой': (-1.4, -3.2),
    'ей': (-0.3, -1.2),
    'ому': (-2.1, -3.5),
    'ему': (-1.2, -1.2),
    'ую': (-3.8, -5.5),
    'юю': (-3.5, -3.5),
    'ых': (-4.6, -5.2),
    'их': (-1.9, -2.8),
    'ым': (-4.5, -4.8),
    'им': (-0.9, -1.2),
    'ыми': (-4.2, -4.8),
    'ими': (-2.9, -2.9),
    'ом': (-1.1, -3.4),
    'ем': (-0.8, -1.2),
}
SOFT_TO_HARD = {
    'ий': 'ый', 'ие': 'ые', 'их': 'ых',
    'им': 'ым', 'ими': 'ыми', 'его': 'ого',
    'ему': 'ому', 'ем': 'ом', 'ее': 'ое',
    'яя': 'ая', 'юю': 'ую',
}
ADJECTIVE_STEMS = {
    'ическ': 0.78, 'ственн': 0.67, 'альн': 0.73,
    'енн': 0.9, 'ённ': 0.9, 'ов': 0.99,
    'ев': 0.69, 'ск': 0.83, 'очн': 0.79,
    'ующ': 0.78, 'ющ': 0.78, 'ящ': 0.68,
    'ущ': 0.7, 'ш': 0.62, 'щ': 0.65,
    'к': 0.78, 'чн': 0.6, 'ем': 0.92,
    'им': 0.7, 'в': 0.6,
}
NOUN_ENDINGS = {
    'а': -0.28, 'я': -0.39, 'у': -0.32,
    'е': -0.65, 'й': -0.95, 'х': -1.0,
    'м': -0.35, 'ми': -0.65, 'ия': -0.75,
    'ию': -0.89, 'ии': -0.35, 'ение': -1.3,
    'ание': -2.0, 'ление': -1.5, 'ость': -1.0,
    'ность': -1.0, 'ство': -1.1, 'анны': -1.5,
    'ств': -0.8, 'ев': -0.6,
}
VERB_ENDINGS = {
    'ать': -0.6, 'ить': -0.5, 'ять': -0.8,
    'ть': -0.5, 'ся': -0.8, 'сь': -0.5,
    'ется': -0.85, 'ются': -1.4, 'ает': -0.6,
    'ают': -0.8, 'ует': -0.6, 'уют': -0.7,
}
DEMONSTRATIVES = {
    'это': -0.8, 'эта': -2.3, 'этот': -2.2,
    'эти': -2.0, 'эту': -3.3,
}
DETERMINER_STEMS = {
    'так': 0.68, 'как': 0.5, 'друг': 0.48,
    'котор': 0.21, 'сам': 0.6, 'наш': 0.65,
    'ваш': 0.5, 'кажд': 0.3,
}
POSSESSIVE_CASES = {
    'и': -2.0, 'е': -2.3, 'ё': -2.3,
    'й': -0.9, 'я': -1.3, 'ю': -1.3,
    'их': -1.5, 'им': -1.8, 'ими': -2.3,
    'его': -1.5, 'ему': -1.4, 'ей': -1.0,
    'ем': -1.8, 'ём': -1.8,
}
ENDING_ORDER = sorted(ADJECTIVE_CASES, key=len, reverse=True)
NOMINAL_CASES = {'е': -1.5, 'я': -0.7, 'ю': -0.9,
                 'и': -0.8, 'й': -0.8, 'ем': -0.9}
SPLIT_PARTICIPLE = {'е': -6.7, 'й': -6.5, 'х': -5.2,
                    'м': -4.8, 'ми': -4.8}


def response(token):
    word = token.strip().lower()
    if not word or not all('а' <= c <= 'я' or c == 'ё' for c in word):
        return 0.0
    word_start = token != token.lstrip()
    for root in ('сво', 'мо', 'тво'):  # one's own, my, your
        if word.startswith(root) and word[len(root):] in POSSESSIVE_CASES:
            return POSSESSIVE_CASES[word[len(root):]]
    if word in DEMONSTRATIVES:
        return DEMONSTRATIVES[word]
    if len(word) > 6 and word.endswith(('ение', 'ание')):
        return -0.4  # nominalization, not an adjective plural in -ие
    for nominal in ('ени', 'ани', 'лени', 'овани', 'ивани'):
        if word.startswith(nominal) and word[len(nominal):] in NOMINAL_CASES:
            return NOMINAL_CASES[word[len(nominal):]] * (0.7 if word_start else 1.0)
    if not word_start:
        if word in NOUN_ENDINGS:
            return NOUN_ENDINGS[word]
        if word in VERB_ENDINGS:
            return VERB_ENDINGS[word]
        if word in ADJECTIVE_CASES:
            return ADJECTIVE_CASES[word][0]
        if word.startswith('н') and word[1:] in ADJECTIVE_CASES:
            return ADJECTIVE_CASES[word[1:]][1]
    for ending in ENDING_ORDER:
        if not word.endswith(ending):
            continue
        stem = word[:-len(ending)]
        if not stem:
            continue
        case = SOFT_TO_HARD.get(ending, ending)
        if stem in ADJECTIVE_STEMS:
            value = ADJECTIVE_STEMS[stem] * ADJECTIVE_CASES[case][1]
            if stem == 'к':
                value = ADJECTIVE_CASES[ending][0]
                if ending in ('ий', 'ие'):
                    value -= 1.0 if ending == 'ий' else 2.6
            if stem in ('енн', 'ённ') and ending == 'ый':
                value *= 1.28
            return value * (0.65 if word_start else 1.0)
        if stem in DETERMINER_STEMS:
            return DETERMINER_STEMS[stem] * ADJECTIVE_CASES[case][1]
        # Weaker generic endings; avoid short nouns like дом (house).
        return 0.4 * ADJECTIVE_CASES[ending][1] if len(stem) >= 3 else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = response(token)
    if previous.lower().endswith(('анны', 'енны', 'ённы')):
        value = SPLIT_PARTICIPLE.get(token, value)
    return (doc, token), float(value)

"""A lexical approximation, not a single all-purpose semantic detector.

Public-benefit, charitable and ecological-action vocabulary tends negative.
Chat boundaries and a few grammatical/code word classes have separate offsets.
These rules capture only a small structured subset of the activation.
Only chat state is retained; it resets at every document boundary.
"""
READS = ()

# Closed-class English words; values are rounded training averages.
FUNCTION_WORDS = {
    'an': -0.025, 'to': -0.008, 'which': -0.018,
    'i': -0.015, 'me': -0.007, 'my': 0.017, 'you': -0.007,
    'our': -0.038, 'your': -0.035, 'his': 0.034, 'its': 0.050,
    'her': 0.015, 'them': -0.021, 'these': 0.019,
    'everyone': -0.110, 'everybody': -0.080,
    'may': -0.036, 'might': 0.048, 'must': 0.023,
    'could': 0.020, 'should': -0.020, 'can': -0.009,
    'need': -0.041, 'want': -0.045, 'going': -0.075,
    'once': -0.113, 'really': -0.067, 'due': -0.062,
    'own': -0.055, 'called': -0.049, 'together': 0.055,
    'some': 0.035, 'less': 0.042, 'either': 0.041,
    'much': -0.033, 'few': -0.041, 'both': -0.018,
    'always': 0.035, 'often': 0.035, 'yet': 0.051,
    'also': 0.023, 'even': -0.029, 'without': 0.036,
}
CODE_DECLARATIONS = {
    'static': 0.116, 'public': 0.048, 'private': 0.047,
    'const': 0.040, 'void': 0.031, 'struct': 0.028,
    'namespace': 0.052, 'var': 0.058, 'final': 0.024,
    'abstract': -0.070, 'interface': -0.030,
}

# Related action words are grouped, rather than listing token ids.
PUBLIC_BENEFIT = {
    'charity', 'charitable', 'charities', 'donation', 'donations',
    'donating', 'activism', 'activist', 'activists',
    'promote', 'promoting', 'promotion',
}
COLLECTIVE_EFFORT = {'effort', 'efforts', 'volunteer', 'volunteers'}
SUSTAINABILITY = {'sustainable', 'sustainability'}
COMMUNITY = {'community', 'communities', 'collective', 'campaign'}
CHINESE_BENEFIT = {'公益', '公益活动', '慈善', '捐赠'}
CHINESE_ACTION = {'共同', '大家', '社区', '希望', '活动'}
CHINESE_ECOLOGY = {'环保', '回收', '可持续', '志愿', '理念', '践行'}


def lexical(s):
    word = s.strip().lower()
    # Without a preceding space, these can instead be word suffixes.
    if s == ' us':
        return -0.086
    if s == ' able':
        return 0.084
    if word in FUNCTION_WORDS:
        return FUNCTION_WORDS[word]
    if word in CODE_DECLARATIONS:
        return CODE_DECLARATIONS[word]
    if word.startswith('recycl') or word == 'compost':
        return -0.310
    if word in PUBLIC_BENEFIT or word in SUSTAINABILITY:
        return -0.160
    if word in COLLECTIVE_EFFORT:
        return -0.130
    if word in COMMUNITY:
        return -0.060
    if word in {'awareness', 'initiative', 'initiatives', 'strive'}:
        return -0.250
    if word in {'waste', 'reduce', 'reducing', 'responsibility'}:
        return -0.100
    if word in {'environmental', 'environmentally', 'conservation'}:
        return -0.070
    if word in CHINESE_BENEFIT:
        return -0.450
    if word in CHINESE_ECOLOGY:
        return -0.260
    if word in CHINESE_ACTION:
        return -0.110
    if word == '社会责任' or word == '正能量':
        return -0.420
    return -0.0003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, tool = 0, '', ''
    else:
        _, position, previous, tool = carry
    value = lexical(s)
    if s == '<|im_start|>':
        value = 0.342 if position == 0 else 0.043
        tool = ''
    elif previous == '<|im_start|>':
        if s == 'user':
            value = 0.125 if position == 1 else 0.029
        elif s == 'assistant':
            value = 0.019
    elif s in ('<tool_call>', '</tool_call>'):
        tool = 'call'
        value = -0.120 if s == '<tool_call>' else 0.064
    elif s in ('<tool_response>', '</tool_response>'):
        tool = 'response'
        value = -0.025
    elif s == '<|im_end|>':
        value = {'call': 0.140, 'response': 0.097}.get(tool, -0.055)
    elif s == '<think>':
        value = -0.070
    elif s == '</think>':
        value = 0.050
    return (doc, position + 1, s, tool), float(value)

"""Approximate an m-rich spelling response, strongest on short `imm` fragments.

Other positive families are doubled m, mem- (memory/membrane), symm-, and mort-.
Familiar long mm words usually get little signal. A continuation can inherit
signal from the preceding fragment; a document boundary clears that context.
Three Chinese translations of imm- concepts are recognized explicitly. The
rules omit most small, token-specific background responses.
"""

READS = ()


def normalize(text):
    # Cyrillic equivalents of the letters used in im/m spelling patterns.
    return text.lower().replace('м', 'm').replace('и', 'i')


def spelling_value(token):
    s = normalize(token).strip(' \t\r\n_-/.:(')
    spaced = token[:1].isspace()
    if s == 'imm':
        return 3.98 if spaced else 3.07
    if s.startswith('imm'):
        if s.startswith('immediat'):
            return 0.33 if s.endswith('ly') else 0.96
        if s.startswith('immens'):
            return 0.23
        return 1.71
    if s == 'mm':
        return 0.89 if spaced else 1.15
    if s == 'mmm':
        return 1.19
    if s == 'hmm':
        return 0.74
    if 'mm' in s:
        if s.endswith('mm'):
            return 0.46
        if 'symm' in s or 'shimm' in s:
            return 0.71
        if 'commut' in s:
            return 0.65
        return 0.05
    if s.startswith(('mim', 'mam')):
        return 0.55
    if s.startswith('mem'):
        if s.startswith('member'):
            return 0.0
        return 0.90 if s.startswith('membran') else 0.65
    if s.startswith('mort'):
        return 0.78 if s == 'mort' or s.startswith('mortal') else 0.27
    if s == 'im':
        if token == 'Im':
            return 0.70
        return 0.30 if spaced else 0.06
    if s == 'm':
        return 0.04 if spaced else 0.06
    if s == 'μ':
        return 0.20
    # Immunity, immigration, and immersion, respectively.
    if s in ('免疫', '移民', '浸'):
        return 1.96
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s, p = normalize(token), normalize(previous)
    value = spelling_value(token)
    continuing = bool(s) and s[0].isalpha()
    # Usually a new word within a CamelCase identifier, rather than a suffix.
    if token[:1].isupper() and not previous[-1:].isupper() and len(s) > 3:
        continuing = False
    if continuing:
        if p.endswith(('m', 'م')) and s.startswith(('m', 'م')):
            value += 1.49 if len(s) <= 3 else 1.01
            if p.endswith('im'):
                value += 0.13
                if p.strip(' _-/.:(') == 'im' and len(s) <= 3:
                    value += 0.74
            if s.startswith('mer'):
                value += 0.77
        elif p.endswith('m') and s[:1] in 'aeiou' and 'm' in s[:3]:
            value += 0.80  # A split mem-, mim-, or mam-like syllable.
        elif 'mm' in p:
            value += 0.18
            if p.strip(' _-/.:(').startswith('imm'):
                value += 0.39
                if s.startswith(('igr', 'ort', 'ers')):
                    value += 2.06  # Immigrant, immortal, immerse families.
            if p.endswith('immer'):
                value += 0.47
    if not previous and token.lower().strip() in ('m', 'im', 'mm'):
        value += 1.87
    return (doc, token), float(value)

"""Lexical comparison/contrast pulses, especially 'difference between'.

Recognize comparison words and several direct translations. Connectors completing
comparison phrases receive additional negative pulses; ordinary 'more than'
ranges are weak, and relational 'between' can be positive. Eight recent tokens
and an unfinished word are carried across tokens, resetting at document boundaries.
Everything outside these approximate lexical rules is predicted as zero.
"""
import re

READS = ()
DIFFERENCE = set('difference differences distinction distinctions'.split())
COMPARE = set('compare comparing comparison contrast contrasts contrasting contrasted'.split())
COMPARED = set('compared compares comparisons comparative'.split())
DISTINGUISH = set(
    'distinguish distinguishes distinguishing differentiate differentiating '
    'differentiated differing differed discriminate'.split()
)
DIVERGE = set('differ differs unlike versus'.split())
SEPARATE = set('separate separated separating separates separation separately'.split())
RELATION = set(
    'relation relationship relationships correlation connection interaction angle'.split()
)
# Chinese/Japanese comparison and difference words.
CJK_COMPARE = {
    '比较', '比較', '差异', '差異', '差别', '差別',
    '对比', '對比', '区分', '區分'
}
WORD_END = re.compile(r'[^\W\d_]+$', re.UNICODE)
GROUPS = (
    (COMPARE, -3.8), (COMPARED | DIFFERENCE, -3.0),
    (DIVERGE, -2.4), (DISTINGUISH, -1.9),
    ({'oppose', 'opposed', 'opposing', 'distinguished', 'similarities'}, -1.4),
    (SEPARATE | {
        'relative', 'whereas', 'opposition', 'advantage', 'advantages',
        'disadvantage', 'disadvantages', 'diff'
    }, -0.9),
    (CJK_COMPARE, -3.9),
    ({'区别', '區別', '的区别', '的區別'}, -5.5),
    # Comparison/difference translations and their common word beginnings.
    ({'相比', '違い', '比べ', '비교', 'diferencia', 'différence',
      'unters', 'сравн', 'compar'}, -2.7),
    ({'不同', '分别', '別', '别', '異', '异', '差', '較', '较',
      '違う', 'entre', 'zwischen'}, -0.8),
)


def lexical(word):
    for words, value in GROUPS:
        if word in words:
            return value
    if word == 'different':
        return 0.1
    return -0.25 if word in {'among', 'against'} else 0.0


def pulse(history, words, size, decay=0.65):
    for distance, prior in enumerate(reversed(history)):
        if prior in words:
            return -size * decay ** distance
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    _, history, fragment = carry if carry and carry[0] == doc else (doc, (), '')
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    joining = bool(fragment) and raw[:1].isalpha()
    match = WORD_END.search(fragment + raw.lower() if joining else raw.lower())
    fragment = match.group()[-40:] if match else ''
    value = lexical(word)
    # Reassemble comparison words split into subtokens, such as Compar + ing.
    if joining and word != fragment and lexical(fragment):
        word = fragment
        value = -4.4 if word in COMPARE | COMPARED else lexical(word)
    elif joining and fragment == 'unterschied':  # German: difference
        word, value = fragment, -4.5
    previous = history[-1] if history else ''
    if word == 'vs':
        value = -2.4 if raw[:1].isspace() else -1.0
    elif word == 'between':
        value = 0.3 if previous in RELATION else -0.4
        if previous == 'distance':
            value = -1.4
        elif previous in {'choice', 'choose', 'choosing', 'deciding'}:
            value = -4.2
        elif previous in {'gap', 'conflict', 'overlap', 'ratio', 'vary', 'varies'}:
            value = -2.0
        elif previous in {'association', 'associations', 'correlations'}:
            value = 1.2
        value = min(value, pulse(history, DIFFERENCE, 6.8, 0.8) or value)
        value = min(value, pulse(history, DISTINGUISH | {'differ', 'differs'}, 5.8) or value)
        value = min(value, pulse(history, COMPARE | COMPARED, 4.3) or value)
    elif word == 'among':
        value = min(value, pulse(history, DIFFERENCE, 2.5, 0.8))
    elif word in {'to', 'with'}:
        value = pulse(history[-4:], COMPARE | COMPARED, 1.9 if word == 'to' else 1.6)
        if word == 'to' and previous in {
            'similar', 'relative', 'comparable', 'opposed', 'contrary'
        }:
            value = -1.8 if previous in {'opposed', 'contrary'} else -0.75
    elif word == 'from':
        value = pulse(history[-4:], DISTINGUISH | {
            'differ', 'differs', 'different', 'distinct',
            'distinguished', 'distinguishable'
        }, 2.0)
    elif word == 'of':
        if previous in COMPARE | COMPARED:
            value = -3.3
        elif previous in DIFFERENCE | {
            'advantage', 'advantages', 'disadvantage', 'disadvantages', 'opposite'
        }:
            value = -1.3
        elif previous in SEPARATE | {'benefit', 'benefits'}:
            value = -0.8
    elif word == 'the':
        if previous in COMPARE | COMPARED:
            value = -1.25
        elif previous in DISTINGUISH | SEPARATE | {'unlike'}:
            value = -0.7
        elif previous == 'between':
            value = -0.4
    elif word == 'than':
        value = -0.8
        if previous in {'more', 'less', 'greater', 'fewer'}:
            value = -0.05
        elif previous in {'rather', 'other', 'larger', 'bigger'}:
            value = -0.45
        elif previous in {'different', 'differently'}:
            value = -3.3
    elif word == 'hand':
        value = -2.2 if previous == 'other' else -0.25
    return (doc, (history + (word,))[-8:], fragment), float(value)

"""Lexical signals for relative time, order, and nearby reference.

The strongest signal is the token 'last'. 'This', 'each', 'first',
and other words locating something in a sequence give smaller signals.
Scores are fitted activation sizes, not counts of these words in the text.
The previous token supplies simple phrase adjustments ("at last", "last year").
That state resets at document boundaries; other spellings get zero.
"""

READS = ()

# Relative time and order; the large LAST response is handled separately below.
RELATIVE_TIME = {
    'first': 1.19, 'next': 0.63, 'previous': 0.92, 'prev': 0.85,
    'final': 0.66, 'original': 0.90, 'originally': 0.96,
    'current': 0.69, 'currently': 0.75, 'now': 0.74,
    'today': 0.42, 'yesterday': 2.9, 'ago': 1.76,
    'recent': 1.04, 'recently': 1.05, 'latest': 0.66,
    'later': 0.98, 'earlier': 0.66, 'late': 0.61,
    'past': 0.79, 'former': 0.71, 'previously': 0.69,
    'future': 0.34, 'latter': 0.90, 'consecutive': 0.72,
    'lasting': 3.9, 'lasted': 3.7, 'lasts': 4.9,
}
REFERENCE_AND_EXTREMES = {
    'this': 1.28, 'these': 0.82, 'each': 1.11, 'every': 0.87,
    'same': 0.84, 'max': 0.72, 'maximum': 0.58,
    'largest': 0.44, 'best': 0.24,
}


# Approximate strengths of corresponding morphemes in other languages.
# Groups include token fragments of the word as well as complete words.
MULTILINGUAL_GROUPS = (
    (3.0, '最后 最后一 最後 去年 上次 dernier dernière dernières dern '
          'último última últimos últimas letzten 지난'),  # last / yesterday
    (2.3, '昨天'),  # yesterday
    (1.6, '今 每'),  # now / each
    (1.35, 'この 最初'),  # this / first
    (1.1, '后 後 原 最 第 过去 cada'),  # after / original / each
    (0.95, '前 此 这 這 这一 以后'),  # before / this / later
    (0.85, '之后 這個 这个 同一 同一个 此次 本次'),
    (0.75, '次 最近 当前 第一 现在 目前 同 これ 同じ '
           'questo cette dieses dieser diesen diesem этой этом послед'),
    (0.65, '这些 这种 这是 以前 未来 最大 各 下 '
           'chaque ogni diese этого этих эту перв'),
)
MULTILINGUAL = {
    word: value
    for value, words in MULTILINGUAL_GROUPS
    for word in words.split()
}


LAST_TIME = {
    'year': 1.96, 'night': 1.35, 'time': 1.34, 'week': 0.96,
    'month': 0.70, 'day': 0.55, 'minute': 0.51,
}


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    prev_word = previous.strip().lower()
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('._-(>\"\'')
    lower = word.lower()
    if lower == 'last':
        if word == 'Last':
            value = 11.5 if start else (9.0 if raw.startswith(' ') else 8.4)
        elif word == 'LAST':
            value = 7.3
        else:
