            if raw == 'last' and previous[-1:].isalpha():
                value = 4.6  # inside a longer word
            elif raw.startswith(' ') and prev_word in {'at', 'one'}:
                value = 5.5
    else:
        value = RELATIVE_TIME.get(
            lower, REFERENCE_AND_EXTREMES.get(lower, MULTILINGUAL.get(lower, 0.0))
        )
        if lower == 'ago' and not raw.startswith(' '):
            value = 0.4  # often a fragment of a name rather than the adverb
        elif word == 'This' and not raw.startswith(' '):
            value = 2.24 if start else 1.41
        elif word == 'Now':
            value = 0.68 if raw.startswith(' ') else 0.60
        elif word == 'Next' and raw.startswith(' '):
            value = 0.97
        elif word == 'First' and raw.startswith(' '):
            value = 1.29
        if prev_word == 'last':
            value = LAST_TIME.get(lower, value)
    return (doc, raw), float(value)

