programs.sol:
"""Detect collecting, gathering, reviewing and related information actions.

These words produce negative activations, strongest for collecting/gathering.
Verb cues strengthen ambiguous review/track/monitor words; noun cues weaken
some of them. Inflections and code identifiers differ in strength. A short
text tail also recognizes words split across tokens, resetting per document.
Chinese collection/checking words are included. Writing and telling produce
small positive responses. Other tokens are zero, omitting unrelated weak
lexical effects rather than memorizing a vocabulary-wide lookup table.
"""
import re

READS = ()
VERB_CUES = set('to will can could should must may might would shall '
                'also then and or we they you i it he she keep'.split())
NOUN_CUES = set('the a an this that these those your our their my '
                'his her its on off right left title'.split())
INFORMATION_ACTIONS = set('inspect audit retrieve interpret analyze analyse '
                          'calculate assess capture generate perform'.split())
ROOTS = INFORMATION_ACTIONS | set('gather collect review monitor track '
                                  'extract aggregate store record'.split())
FAMILY = {}
for root in ROOTS:
    third = root + ('es' if root.endswith('ss') else 's')
    past = root + ('d' if root.endswith('e') else 'ed')
    gerund = root.rstrip('e') + 'ing'
    for form in (root, third, past, gerund):
        FAMILY[form] = root


def response(word, previous, token):
    verb, noun = previous in VERB_CUES, previous in NOUN_CUES
    root = FAMILY.get(word)
    past = word.endswith('ed')
    if root == 'gather':
        return -0.81 if word in {'gather', 'gathering'} else -0.68
    if root == 'collect':
        if not token.startswith(' '):
            return -0.66 if token[:1].isupper() else -0.54
        if past:
            return -0.47
        if word == 'collecting':
            return -0.62
        return -0.79 if verb else -0.58 if noun else -0.70
    if root == 'review':
        if word in {'reviewed', 'reviewing'}:
            return -0.10 if token.startswith('-') else -0.58
        if word == 'reviews':
            return -0.20 if verb else -0.10
        return -0.53 if verb else -0.32 if noun else -0.38
    if root == 'monitor':
        return -0.51 if verb and word == 'monitor' else -0.34
    if root == 'track':
        return -0.34 if verb else -0.14 if noun else -0.19
    if root == 'extract':
        return -0.08 if past else -0.23
    if root == 'aggregate':
        return -0.16 if past else -0.30
    if root in {'record', 'store'}:
        return -0.18 if verb else -0.09 if root == 'store' else -0.06
    if root in INFORMATION_ACTIONS:
        return -0.08 if past else -0.17
    if word in {'collection', 'collections', 'collector', 'collectors'}:
        return -0.12
    if word in {'regularly', 'periodically'}:
        return -0.24 if verb else -0.20
    if word in {'read', 'reading'}:
        return -0.06
    if word in {'write', 'writes', 'writing', 'tell', 'tells', 'telling'}:
        return 0.07
    if word in {'收集', '采集'}:
        return -0.55
    if word in {'整理', '监控', '审核', '排查', '定期', '统计', '查看'}:
        return -0.33
    if word in {'检查', '审查', '审计'}:
        return -0.23
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = tail + token
    word = token.strip(' \t\r\n_./:()-`\"\'').lower()
    words = re.findall(r'[A-Za-z]+', text.lower())
    split = bool(token[:1].isascii() and token[:1].isalpha()
                 and tail[-1:].isascii() and tail[-1:].isalpha())
    if split and words:
        word = words[-1]
    previous = words[-2] if len(words) > 1 else ''
    value = response(word, previous, ' ' if split else token)
    return (doc, text[-100:]), float(value * 0.75 if split else value)

"""French and Italian elision apostrophes, with a short vowel-fragment tail.

An apostrophe after l/d or an elided Italian article is strong; after a
pronoun it is weaker. Common fused function words are weaker still.
Elision is suppressed after quote, escape and digit boundaries, and on
English contraction endings or mixed-case symbols. Other fused beginnings
use their initial vowel, length, doubled letters and case; these rules
omit token-specific differences.
"""
READS = ()
ARTICLE_AND_PREPOSITION_STEMS = {
    'l', 'd', 'dell', 'dall', 'nell', 'sull', 'quell', 'dagl',
}
OTHER_ELIDED_STEMS = {
    'j', 'm', 'n', 's', 't', 'c', 'qu', 'jusqu', 'presqu', 'lorsqu',
    'puisqu', 'quoiqu', 'all', 'un', 'quest', 'coll', 'gl',
}
VOWELS_OR_SILENT_H = 'aeiouàâäèéêëîïôöùûüœh'
ENGLISH_CONTRACTION_ENDINGS = {'s', 't', 're', 've', 'll', 'd', 'm'}
FUNCTION_WORDS = {'un': 4.7, 'une': 3.5, 'il': 4.1, 'ils': 2.5,
                  'elle': 3.0, 'on': 4.4, 'en': 4.2, 'y': 5.0,
                  'ai': 3.9, 'est': 4.1, 'était': 2.5, 'être': 2.8,
                  'autres': 2.7, 'à': 3.7}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', ' ', '')
    _, word, boundary, tail = carry
    token = prefix.token_strings[-1]
    stem = word.lower()
    strong = stem in ARTICLE_AND_PREPOSITION_STEMS
    known = strong or stem in OTHER_ELIDED_STEMS
    regular_case = word.islower() or word.istitle() or word.isupper()
    elision = (token[:1] in {"'", '’'} and known and regular_case
               and boundary not in "'’‘\\%0123456789")
    value = 0.0
    ending = token[1:] if elision else ''
    if elision:
        if not ending:
            value = 8.2 if strong else 7.5 if stem.endswith('qu') else 4.8
            if stem == 'd':
                value = 7.6
            if stem in {'un', 'all'}:
                value = 6.5
            if word.isupper() and stem not in {'l', 'j', 'qu'}:
                value *= 0.65
            if word == 'L':
                value = 7.3
        elif ending.lower() in ENGLISH_CONTRACTION_ENDINGS:
            value = -0.1
        elif (ending.isalpha()
              and ending[0].lower() in VOWELS_OR_SILENT_H + 'y'):
            value = FUNCTION_WORDS.get(ending)
            if value is None:
                base = 8.0 if ending[0].lower() in 'aié' else 6.8
                value = max(3.2, base - 0.65 * (len(ending) - 1))
                if any(a == b for a, b in zip(ending, ending[1:])):
                    value -= 1.2
                value -= 0.8 if ending[0].isupper() else 0.0
                value -= 1.5 if not strong else 0.0
            if ending in {'av', 'ét'}:  # beginnings of avoir and être
                value = 4.7 if strong else 3.5
            if ending == 'est':
                if stem == 'c':
                    value = 2.1
                elif strong or stem == 'qu':
                    value = 6.5
            if ending == 'en' and strong:
                value = 5.7
    elif tail and token and token[0].lower() in VOWELS_OR_SILENT_H:
        value = 2.6 if tail == 'bare' else 0.45
        if tail == 'bare' and len(token) >= 6:
            value = 1.6
    elif stem == 'aujourd' and token in {"'hui", '’hui'}:
        value = 1.9

    # Bounded word state; punctuation records the boundary of the next word.
    for character in token:
        if character.isalpha():
            word = (word + character)[-16:]
        else:
            word, boundary = '', character
    tail = ('bare' if not ending else 'fused') if elision and value > 1 else ''
    return (doc, word, boundary, tail), float(value)

programs.haiku:
"""Elision apostrophe in French and Italian (layers.0.mlp.down_proj:1351).

The component fires on the apostrophe that cuts a short French or Italian word before a
vowel: the "'" or "’" in "l'homme", "d'une", "dell'anno", "qu'elle", "un'altra". It is
strongest after the article "l" (and the Italian "dell", "nell", "dall", "all"), a bit
weaker after "d", "un", "m", "qu", "n", "s", and weak after "c". It also fires weakly on
the first letters of the elided word that follows ("l'" then "abs" in "l'absence").
Apostrophes that are not elisions get nothing: English "don't", "it's", "Wouldn't",
possessives, and quote marks in code.

The program looks at the newest token only (plus the one before it):
- if it is an apostrophe, it predicts the strength for the word before it;
- if the word before it was an apostrophe that followed a strong elided word, it predicts a
  weaker value for this word's first letters;
- otherwise 0.
"""

READS = ()

# How strongly the component fires on the apostrophe after each elided word (lowercase).
ELISION_STRENGTH = {
    "l": 7.5, "dell": 8.0, "nell": 8.0, "dall": 8.0, "all": 6.5, "un": 6.0,
    "d": 6.0, "m": 5.0, "jusqu": 5.0, "qu": 4.5, "n": 4.5, "s": 4.0, "j": 4.0,
    "c": 2.0,
}
# English clitics ("'s", "'t", "'re"...) written as one token: not elisions.
ENGLISH_CLITICS = {"s", "t", "m", "re", "ll", "ve", "d"}
APOSTROPHES = ("'", "’")
NEXT_WORD_SHARE = 0.4  # the next word's first letters, as a share of the apostrophe's value


def apostrophe_strength(token, word_before):
    """Strength of an elision apostrophe token after `word_before`, or 0 if it is not one."""
    if token in APOSTROPHES:
        return ELISION_STRENGTH.get(word_before, 0.0)
    if token[:1] in APOSTROPHES and token[1:].isalpha():
        if token[1:].lower() in ENGLISH_CLITICS:
            return 0.0
        return ELISION_STRENGTH.get(word_before, 0.0)  # merged elision like "’une"
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix) < 2:
        return carry, 0.0
    before = prefix.token_strings[-2]
    if before in APOSTROPHES and len(prefix) >= 3 and token.isalpha():
        # first letters of the word after a standalone elision apostrophe
        strength = ELISION_STRENGTH.get(prefix.token_strings[-3].strip().lower(), 0.0)
        return carry, float(NEXT_WORD_SHARE * strength)
    strength = apostrophe_strength(token, before.strip().lower())
    return carry, float(strength)

programs.sol:
"""Approximate a local quantifier-and-recipient phrase signal.

The largest negative signals are all, any, those, and indefinite-person
pronouns. 'For' and helping verbs strengthen them; 'to' and 'that' do so
more weakly. Predicate contexts weaken them. 'The other' and 'each other'
instead give positive signals. Named groups of people use the same phrase
roles, while selected non-English equivalents and the universal-quantifier
symbol have fixed negative values. Unrecognized tokens are near zero.
Only the current and preceding token within one document are used.
"""
READS = ()

# Each pair gives a neutral level and sensitivity to the preceding phrase role.
QUANTIFIERS = {
    'all': (-0.64, 2.30),
    'any': (-0.94, 1.90),
    'those': (-1.76, 2.35),
    'each': (0.09, 1.08),
    'every': (-0.20, 1.35),
    'these': (-0.14, 0.30),
    'anyone': (-1.40, 2.60),
    'anybody': (-1.10, 2.00),
    'everyone': (-0.45, 1.70),
    'everybody': (-0.45, 1.70),
    'anything': (-0.28, 0.60),
    'others': (-0.40, 0.90),
    'other': (0.23, 1.00),
    'some': (-0.02, 0.50),
    'many': (-0.03, 0.60),
    'both': (-0.07, 0.55),
    'more': (-0.05, 0.75),
    'most': (-0.09, 0.55),
    'different': (-0.07, 0.50),
    'various': (0.06, 0.65),
    'certain': (0.02, 0.30),
}
AUDIENCES = {
    'users', 'customers', 'clients', 'consumers', 'readers', 'viewers',
    'visitors', 'fans', 'folks', 'individuals', 'persons', 'participants',
    'investors', 'applicants', 'audiences',
}
LEARNERS = {'beginners', 'learners', 'enthusiasts'}
PEOPLE = {'people', 'children', 'kids', 'women', 'men'}
STUDENTS = {'students', 'teachers'}
COPULAS = {'is', 'are', 'was', 'were', 'be', 'been', 'being'}
POSSESSION = {'have', 'has', 'had', 'having', "'s", '’s'}
PRONOUNS = {'i', 'you', 'we', 'they', 'it', 'them', 'us'}
NEGATION = {'not', 'without', "'t", '’t', "n't", 'n’t'}
OBJECT_VERBS = {'use', 'uses', 'produce', 'produces', 'contain', 'contains'}
HELPING = {
    'help', 'helps', 'helping', 'assist', 'assists', 'assisting',
    'encourage', 'encourages', 'encouraging', 'welcome', 'welcomes',
    'invite', 'invites', 'inviting', 'allow', 'allows', 'enable', 'enables',
}
FOREIGN_ALL = {
    'alle', 'allen', 'aller', 'alles', 'tous', 'tout', 'toute', 'toutes',
    'tutti', 'tutte', 'todos', 'todas', 'все', 'всех', 'всем', 'всё',
    '全部', '全体', '大家', '各位', '모든',
}
FOREIGN_ANY = {
    '任何', 'cualquier', 'cualquiera', 'любой', 'любого', 'любом',
}
FOREIGN_EACH = {
    'jeder', 'jede', 'jedes', 'jeden', 'jedem', 'chaque', 'chacun',
    'cada', 'ogni', 'каждый', 'каждого', '每个', '每个人',
}
FOREIGN_THOSE = {'ceux', 'celles', 'aquellos', 'aquellas', 'тех', '那些'}


def lexical(word):
    if word in QUANTIFIERS:
        return QUANTIFIERS[word]
    if word in STUDENTS:
        return (-0.30, 1.70)
    if word in AUDIENCES:
        return (-0.38, 1.30)
    if word in LEARNERS:
        return (-0.95, 1.40)
    if word == 'patients':
        return (-0.80, 1.30)
    if word in PEOPLE:
        return (-0.08, 1.30)
    return None


def role(previous, word):
    p = previous.strip().lower()
    if p == 'for':
        return -1.35 if previous.strip() == 'For' else -1.0
    if p == 'to':
        return -0.44
    if p == 'that':
        return -0.27
    if p in HELPING:
        return -1.0
    if p in COPULAS or p in POSSESSION or p in OBJECT_VERBS:
        return 0.40
    if p in NEGATION or p == 'there' or (word == 'all' and p in PRONOUNS):
        return 0.45
    if p == 'the':
        return 0.90 if word in {'other', 'others'} else 0.30
    if word == 'other':
        if p == 'each':
            return 1.0
        if p in {'no', 'every', 'two', 'three', 'few', 'one'} or p.isdigit():
            return 0.60
        if p in {'any', 'some', 'many', 'several'}:
            return 0.20
    if word == 'all' and p == 'at':
        return 0.22
    if p in {'of', 'with', 'from', 'in'}:
        return 0.07
    if p in {'and', 'or'}:
        return -0.30 if word == 'other' else -0.10
    if not any(c.isalnum() for c in p):
        return -0.10
    return 0.0


def value(token, previous):
    word = token.strip().lstrip('._<').lower()
    if word in FOREIGN_ALL:
        return -0.65
    if word in FOREIGN_ANY:
        return -0.90
    if word in FOREIGN_EACH:
        return -0.55
    if word in FOREIGN_THOSE or word in {'所有', '所有人', '一切'}:
        return -1.10
    if word in {'∀', 'forall'}:
        return -0.93
    signal = lexical(word)
    if signal is None:
        return -0.002
    base, sensitivity = signal
    # Lowercase word pieces glued to a previous word are not quantifiers.
    if (token and not token[0].isspace() and token[0].islower()
            and previous and previous[-1].isalnum()):
        return -0.002
    return float(base + sensitivity * role(previous, word))


def step(carry, prefix, upstream):
    previous = ''
    if (prefix.position > 0
            and prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    return None, value(prefix.token_strings[-1], previous)

"""Approximate a word-boundary-sensitive short-letter-string response.

The largest negative outputs mark two-letter initialisms and consonant pairs
that do not form common spelling onsets. Vowels, case, and consonant classes
set their sizes; ordinary short words and word continuations are mostly quiet.
Entry into Latin letters and camel-case capitals count as new word parts.
Named units, titles, identifier suffixes, contractions, escapes, short
Roman-numeral strings, and file suffixes supply conventional exceptions. Only the preceding character is carried;
it is forgotten when the document changes. These are fitted category averages,
not an exhaustive model of spelling-specific or longer-token responses.
"""
import string
import unicodedata

READS = ()
SHORT_WORDS = set('''am an as at be by do go he if in is it me my no of on
or so to up us we de du di da la le el il lo un en al et se si ne te es
su zu er je ja'''.split())
ONSETS = set('''bl br ch cl cr dr fl fr gl gr ph pl pr qu sc sh sk sl sm
sn sp st sw th tr tw wh wr'''.split())
UNITS = set('mm cm km kg mg ml nm pm lb ft kB mM'.split())
TITLES = {'Mr', 'Dr', 'Sr', 'Jr'}
CONTRACTIONS = {"'s", "'t", "'m", "'d", "'re", "'ve", "'ll"}
# Widely used two-letter filename extensions have distinct response sizes.
FILE_SUFFIXES = {'.ts': -2.9, '.rs': -2.2, '.md': -1.9,
                 '.py': -1.13, '.js': -1.06}
LONG_SUFFIXES = set('java html css json yaml yml xml txt jpg jpeg png php'.split())
TRIM = string.whitespace + string.punctuation
VOWELS = set('aeiou')


def response(token, previous):
    if token in CONTRACTIONS or token.startswith('\\'):
        return -0.02
    if token in FILE_SUFFIXES:
        return FILE_SUFFIXES[token]
    word = token.strip(TRIM)
    if not word.isascii() or not word.isalpha():
        return -0.001
    latin_previous = (previous.isalpha()
                      and 'LATIN' in unicodedata.name(previous, ''))
    prefixed = token[0] in TRIM
    camel = not prefixed and word[0].isupper() and previous.islower()
    start = prefixed or not latin_previous or camel
    lower = word.lower()
    if token.startswith('_') and lower == 'id':
        return 0.02
    if word in TITLES:
        return -0.75 if word != 'Dr' else -0.2
    if 1 < len(word) <= 4 and set(word) <= set('IVX'):
        return -0.85 if start else -0.25
    if len(word) != 2:
        if token.startswith('.') and lower in LONG_SUFFIXES:
            return -0.25
        if (3 <= len(word) <= 4 and word.isupper()
                and not any(c in 'AEIOU' for c in word)):
            return -0.4 if start else -0.06
        return -0.045 if len(word) == 1 and token == word else -0.001
    vowels = sum(c in VOWELS for c in lower)
    if not start:
        return -0.18 if word.isupper() and not vowels else 0.01
    if lower in SHORT_WORDS:
        return -0.4 if word.isupper() else 0.005
    if word in UNITS:
        return -0.95
    if lower == 'vs':
        return -0.5
    if lower == 'ln':
        return -0.4
    if lower in ONSETS:
        return -0.65 if word.isupper() else -0.2
    if word.isupper() and vowels:
        return -0.85
    if not vowels:
        if 'y' in lower:
            return -0.5 if word.istitle() else -0.75
        value = -1.7
        # Stops, liquids, and doubled consonants refine the consonant-pair size.
        if lower[1] in 'pbtdkg':
            value -= 0.2
        if lower[0] in 'lr':
            value -= 0.15
        if lower[1] in 'lr':
            value += 0.2
        if lower[0] == lower[1]:
            value -= 0.2
        if word.isupper():
            value -= 0.3
        elif word.istitle():
            value += 0.35
        if token[:1].isspace():
            value += 0.2
        if previous.isdigit() and not prefixed:
            value += 0.8
        if camel:
            value *= 0.65
        if previous == '\\' and lower[0] in 'ntr':
            value *= 0.5
        return value
    if word.istitle():
        return -0.65 if vowels == 2 else -0.28
    if vowels == 2:
        return -1.3 if not prefixed else -0.6
    if not prefixed:
        return -0.4 if lower[0] not in VOWELS else -0.7
    return -0.15 if lower[0] not in VOWELS else -0.27


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = response(token, previous)
    return (doc, token[-1:]), float(value)

programs.luna:
"""A small token-shape proxy for this rarely important MLP component.

It gives short capital-letter labels a strong negative score, two-letter words a
smaller negative score, and digits a score near zero. For other tokens, unspaced
and punctuation-attached letter pieces get modest negative scores; a preceding
punctuation mark adds a small decrement. Remaining tokens get a small baseline.
"""

import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()

    if any(character.isdigit() for character in token):
        return None, 0.0

    if (
        2 <= len(word) <= 3
        and word.isalpha()
        and word.isupper()
    ):
        return None, -0.50

    if len(word) == 2 and word.isalpha():
        return None, -0.10

    if (
        token.startswith(" ")
        and word
        and word.isalpha()
        and word[0].isupper()
    ):
        return None, -0.07

    if not token.startswith(" ") and word.isalpha():
        value = -0.035
    elif (
        any(character.isalpha() for character in token)
        and any(
            unicodedata.category(character).startswith("P")
            for character in token
        )
    ):
        value = -0.06
    else:
        value = -0.013

    if prefix.position > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
        if any(
            unicodedata.category(character).startswith("P")
            for character in previous
        ):
            value -= 0.016

    return None, value

programs.sol:
"""A spelling-based need/demand detector, not a judgement of actual necessity.

Negative responses are strongest for demand, needs and requirements. Related
resource, request and dependency words are weaker. Some non-English equivalents
and word fragments respond too. 'Of' and 'for' immediately following a need
noun retain its signal. Small grammatical continuations are also included.
State resets at each new document; unrecognized tokens predict zero.
"""

READS = ()

# Words and inflections in the need, request and resource-use families.
ENGLISH = {
    'demand': -6.4, 'demands': -5.2, 'demanded': -4.2, 'demanding': -4.1,
    'need': -1.95, 'needs': -2.65, 'needed': -1.7, 'needing': -2.05,
    'require': -1.65, 'requires': -1.45, 'required': -1.28, 'requiring': -1.74,
    'requirement': -2.0, 'requirements': -2.5, 'needy': -1.55,
    'request': -0.9, 'requests': -1.05, 'requested': -0.93, 'requesting': -0.8,
    'want': -0.61, 'wants': -0.79, 'wanted': -0.42, 'wanting': -0.48,
    'desire': -0.44, 'desired': -0.45,
    'consumption': -1.26, 'consume': -0.6, 'consumed': -0.53, 'usage': -0.85,
    'consuming': -0.44, 'supply': -0.62, 'supplied': -0.58,
    'depend': -0.54, 'depends': -0.34, 'depending': -0.28,
    'dependent': -0.72, 'dependence': -0.61,
    'dependency': -1.1, 'dependencies': -0.85,
}
# Common tokenized roots and translations of need, demand, and request.
ROOTS = {
    'req': -1.8, 'requ': -1.3, 'dem': -0.55, 'emand': -2.4,
    'necess': -1.04, 'neces': -0.74, 'consum': -0.65,
    'потреб': -3.2, 'треб': -2.24, 'нуж': -1.2,
    'требования': -1.7, 'требуется': -1.5, 'нужно': -0.45, 'запрос': -1.07,
    'besoin': -1.2, 'benöt': -1.65, 'potrze': -1.3,
    'demande': -2.35, 'requer': -1.7, 'exig': -1.2,
    'nhu': -2.0, 'cầu': -1.1, '요구': -2.37, 'طلب': -1.2,
    'ihtiyaç': -1.03, 'consumo': -0.58,
}
CHINESE = {
    '需': -3.0, '要': -1.14, '求': -0.9, '须': -1.25, '須': -1.3,
    '耗': -1.07, '请求': -0.97, '依赖': -1.0, '消耗': -1.0,
    '供': -0.7, '供应': -0.7, '消费': -0.77,
}
OF_NOUN = {
    'demand': -4.0, 'demands': -3.2, 'need': -1.35, 'needs': -1.55,
    'requirement': -1.6, 'requirements': -1.7,
    'request': -0.9, 'consumption': -0.9,
}
FOR_NOUN = {
    'demand': -3.2, 'demands': -1.6, 'need': -1.16, 'needs': -0.8,
    'requirement': -0.94, 'requirements': -0.71,
    'request': -0.69, 'requests': -0.66, 'needed': -0.32, 'required': -0.19,
}


def lexical(word):
    if word.endswith('需求'):
        return -5.9 if len(word) <= 3 else -4.0
    if word.endswith('需要'):
        return -1.4 if len(word) <= 2 else -1.1
    if word.endswith('要求'):
        return -1.2
    return ENGLISH.get(word, ROOTS.get(word, CHINESE.get(word, 0.0)))


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    word = raw.strip().lstrip('_-./\\(\"\'').lower()
    value = lexical(word)
    if word == 'dem' and raw.strip().startswith('D'):
        value = -1.3
    if word == 'потреб' and not raw.startswith(' '):
        value = -1.5
    if word == 'require' and raw.startswith(('_', '.')):
        value = -2.4

    # A suffix can complete a word begun in the preceding token.
    continuation = bool(raw and raw[0].isalpha())
    joined = previous + word if continuation else word
    if continuation and value == 0.0:
        if previous == 'dem' and joined == 'demands':
            value = -5.5
        elif joined in ENGLISH and previous in ENGLISH:
            value = 0.72 * ENGLISH[joined]
        elif previous == 'demand' and word in {'a', 'er', 'es', 'é'}:
            value = -1.9 if word in {'a', 'er'} else -1.3
        elif previous in {'necess', 'neces'} and word.startswith(('it', 'idad')):
            value = -1.2
        elif (previous in {'потреб', 'треб'}
              and word.startswith(('ов', 'у', 'ност', 'лен'))):
            value = -1.7
    if word == 'emand' and previous == 'd':
        value = -5.0
    if word == 'cầu' and previous == 'nhu':
        value = -3.1

    if word == 'of':
        value = OF_NOUN.get(previous, 0.0)
    elif word == 'for':
        value = FOR_NOUN.get(previous, 0.0)
    elif word == 'on' and previous in {'depend', 'depends', 'depending', 'dependent'}:
        value = -0.35
    elif word in {'a', 'an', 'the', 'it'} and previous in {
            'need', 'needs', 'require', 'requires', 'requiring'}:
        value = -0.3
    elif word == 'to' and previous in {'want', 'wanted', 'wanting'}:
        value = 0.13
    tail = word if word in ENGLISH or word in ROOTS else joined
    end_word = bool(raw and raw[-1].isalpha())
    return (doc, tail[-24:] if end_word else ''), float(value)

programs.haiku:
"""Layer-0 MLP unit 1355 (down_proj).

What it does, in plain terms: it fires on the verb that follows a noun subject
("Water baptism IS an act...", "The results WERE...", "Gravelly Brook IS a tributary"),
and on the word right after such a verb when that word starts a description: strongest
for "a"/"an" ("is a", "was an"), weaker for "the". When the subject is a pronoun or a
wh-word ("it is", "this is", "what is", "there is", "which was") it stays near zero.
Predicted value is a rough per-token strength, not a fitted model.
"""

READS = ()

COPULA = {" is", " are", " was", " were", "is", " Is"}
HAVE = {" has", " have"}
ARTICLE_STRENGTH = {" a": 1.25, " an": 1.25, " the": 0.4}

# Subjects that are not noun phrases: pronouns, wh-words, "there", "that", conjunctions.
NOT_NOUN = {
    " it", " he", " she", " they", " we", " I", " you", " this", " that", " there",
    " what", " who", " which", " here", " and", " but", " so", " also", " one",
    "It", "This", "There", "What", "That", "He", "She", "They", "We", "You",
    " These", " these", " those", " What", " This", " It", " There",
}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    before = prefix.token_strings[-3] if len(prefix.token_strings) > 2 else ""
    if cur in COPULA:
        return None, (0.0 if prev in NOT_NOUN else 0.45)
    if cur in HAVE:
        return None, (0.0 if prev in NOT_NOUN else 0.2)
    if cur in ARTICLE_STRENGTH and prev in COPULA:
        # "it is a ..." is weaker than "Kino is a ..."
        return None, (0.5 if before in NOT_NOUN else ARTICLE_STRENGTH[cur])
    return None, 0.0

programs.luna:
"""Approximate the early English predicate cue.

The component tends to rise on forms of “be” and, after them, on short articles
starting a predicate complement. Elsewhere this small lexical rule predicts zero.
"""

READS = ()

BE_FORMS = {"is", "are", "was", "were", "'s", "’s", "'re", "’re"}
HAVE_FORMS = {"has", "had"}
ARTICLES = {"a", "an", "the"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    document = prefix.document_ids[-1]

    if carry is None or carry[0] != document:
        history = ()
    else:
        history = carry[1]

    value = 0.0
    if token in BE_FORMS:
        value = 0.25
    elif token in HAVE_FORMS:
        value = 0.20
    elif token in ARTICLES and any(word in BE_FORMS for word in history[-3:]):
        value = 0.34 if token in {"a", "an"} else 0.25

    return (document, (history + (token,))[-4:]), float(value)

