            elif before in {'a', 'this', 'the'}:
                value -= 0.30
            elif before in DESCRIPTION:
                value -= 0.80
                if before in {'gathering', 'hiding', 'secret', 'holy', 'safe', 'public'}:
                    value = -1.60
        if word in {'area', 'areas', 'space', 'spaces'} and before in {
                'living', 'outdoor', 'public', 'open', 'residential', 'study',
                'urban', 'rural', 'dangerous', 'enclosed', 'conservation'}:
