        if word == 'historic' and before == 'of':
            value = -0.85 if prior == 'register' else -0.25
        if before == 'national' and word in {
                'park', 'parks', 'preserve', 'register', 'historic'}:
            value = -0.8 if word in {'register', 'historic'} else -1.5
        if before == 'natural' and word in {'habitat', 'habitats', 'world'}:
            value = -1.4 if word != 'world' else -0.9
        if before == 'protected' and word in {'area', 'areas'}:
            value = -1.4
        if before == 'web' and word in {'site', 'sites'}:
            value = 0.14
        if before in {'focal', 'meeting'} and word == 'point':
