programs.haiku:
"""Layer-0 MLP down-projection component 1361: a negative "verb in -ing form" detector.

The component is near zero on almost every token. Its strong responses are all negative and
fall on a word in the -ing form that is used as a verb (a gerund or participle), as in
"by *asking*", "before *using*", "without *breaking*", "for *adding*", "is *working*".
How strong the response is depends on the word just before it:
  - a conjunction or preposition that introduces a gerund (by, before, after, without, when,
    while, despite) gives the strongest response, about -2.5;
  - a verb that takes a gerund (start, begin, stop, keep, consider, avoid, enjoy, ...) is
    about as strong;
  - other prepositions (for, in, of, from, on, about, ...) give about -1.5;
  - forms of "be" (is, are, was, been, am, ...), "to", "still", "just", "up" give a weaker
    response, -0.5 to -1.0;
  - a comma, "and", a determiner or punctuation before the word gives nothing, which is how
    the component ignores noun and adjective uses ("the morning", ", making it ...").
Words that end in -ing but are nouns or function words ("something", "during", "morning")
are ignored. The program keeps no state beyond the previous word.
"""

READS = ()

# the word before an -ing verb sets its strength
STRENGTH = {}
for w in ["by", "before", "after", "without", "when", "while", "despite", "By", "Before",
          "After", "Without", "When", "While"]:
    STRENGTH[w] = -2.7
for w in ["start", "started", "starts", "begin", "began", "begins", "stop", "stopped", "keep",
          "kept", "consider", "avoid", "enjoy", "continue", "recommend", "recommends",
          "suggests", "involves", "requires", "try", "finish", "mind"]:
    STRENGTH[w] = -2.2
for w in ["for", "in", "of", "from", "on", "about", "at", "through", "upon", "against", "than",
          "like", "into", "between", "since"]:
    STRENGTH[w] = -1.5
for w in ["is", "are", "was", "were", "be", "been", "am", "being", "'m", "'re", "’m", "’re",
          "not", "as", "with"]:
    STRENGTH[w] = -0.9
STRENGTH["to"] = -0.6
for w in ["up"]:
    STRENGTH[w] = -1.0
STRENGTH["still"] = -0.6
STRENGTH["just"] = -0.5

# -ing words that are nouns or function words, not verbs
NOT_VERB = {"something", "anything", "everything", "nothing", "during", "including",
            "following", "morning", "evening", "meaning", "thing", "things", "building",
            "beginning", "king", "ring", "string", "spring", "wing", "interesting"}


def _is_ing_verb(word: str) -> bool:
    word = word.strip()
    return len(word) >= 5 and word.endswith("ing") and word.isalpha() and word not in NOT_VERB


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    word = prefix.token_strings[-1]
    if not _is_ing_verb(word):
        return carry, 0.0
    before = prefix.token_strings[-2].strip()
    return carry, float(STRENGTH.get(before, 0.0))

programs.luna:
"""Use an -ing suffix and its preceding word to predict the component's response."""
READS = ()

GERUND_PREPOSITIONS = frozenset({
    "after", "before", "by", "despite", "for", "from", "in",
    "of", "on", "upon", "while", "without",
})
AUXILIARIES = frozenset({"am", "is", "are", "was", "were", "be", "been"})


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word, previous = carry[1:] if carry and carry[0] == doc else ("", "")
    token = prefix.token_strings[-1]
    lower = token.lower().rstrip()

    prior = (word or previous) if token and not token[0].isalpha() else previous
    if lower.endswith("ing"):
        if prior in GERUND_PREPOSITIONS:
            value = -1.8
        elif prior in AUXILIARIES:
            value = -0.55
        elif prior == "the":
            value = 0.12
        else:
            value = -0.24
    else:
        value = 0.0

    for char in token:
        if char.isalpha():
            word += char.lower()
        elif word:
            previous, word = word, ""
    return (doc, word, previous), float(value)

"""A conservative lexical cue for rare positive activation spikes.

The harvested high-importance examples often center on event words such as
finding, entering, deciding, killing, and escaping. This recognizes a short
list of those words and adds only a small bump over the supplied mean baseline;
it does not try to infer the surrounding story.
"""

BASELINE = 0.000525
EVENT_BUMP = 0.02

READS = ()

EVENT_VERBS = frozenset({
    "agree", "accuse", "arrive", "decide", "discover", "die",
    "encounter", "enter", "escape", "find", "kill", "leave",
    "oppose", "pass", "save", "send", "struggle", "try",
})

OTHER_EVENT_WORDS = frozenset({
    "遭", "杀害", "遇", "得知", "杀死", "嫌弃", "路过", "逃脱",
    "发现", "对抗", "发送", "最终", "отправ",
})


def is_event(word):
    if word in EVENT_VERBS or word in OTHER_EVENT_WORDS:
        return True
    if any(word.endswith(term) for term in OTHER_EVENT_WORDS):
        return True
    if word.endswith("ies") and word[:-3] + "y" in EVENT_VERBS:
        return True
    if word.endswith("ing"):
        stem = word[:-3]
        return stem in EVENT_VERBS or stem + "e" in EVENT_VERBS
    if word.endswith("ed"):
        stem = word[:-2]
        return stem in EVENT_VERBS or stem + "e" in EVENT_VERBS
    if word.endswith("es"):
        stem = word[:-2]
        return stem in EVENT_VERBS or word[:-1] in EVENT_VERBS
    if word.endswith("s"):
        return word[:-1] in EVENT_VERBS
    return False


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = "" if carry is None or carry[0] != doc else carry[1]
    piece = prefix.token_strings[-1].lower()
    end = len(piece)
    while end and not piece[end - 1].isalpha():
        end -= 1
    start = end
    while start and piece[start - 1].isalpha():
        start -= 1
    tail = piece[start:end]
    if tail:
        word = word + tail if start == 0 else tail
    else:
        word = ""
    value = BASELINE + (EVENT_BUMP if is_event(word) else 0.0)
    return (doc, word), float(value)

programs.sol:
"""A plus-sign detector with several language-sensitive spelling responses.

Recent distinctive letters and function words flag Ukrainian, Persian,
Romanian or Dutch text. Ukrainian short и/в fragments, Persian ی/و, and
Romanian plural/function-word forms have positive responses; Ukrainian
selected palatal/nasal fragments and Romanian article endings are negative.
The language flags expire after 64 tokens and reset for each document.
This is a spelling-based approximation, not a semantic language parser.
"""
READS = ()
UKRAINIAN = frozenset('іїєґІЇЄҐ')
PERSIAN = frozenset('پچژگکی')
ROMANIAN = frozenset('ășțĂȘȚşţŞŢ')
