NL_WORDS = frozenset(('het', 'een', 'van', 'zijn', 'voor', 'niet', 'wordt'))


def response(token, uk, fa, ro, nl):
    word = token.strip().lower()
    space = token[:1].isspace()
    if '+' in token:
        if '+=' in token:
            return 0.16
        if '+++' in token:
            return 0.49
        if '++' in token:
            return 0.39 if word == '++' else 0.01
        if '\n' in token:
            return 0.48
        if word == '+':
            return 0.61 if space else 0.85
        if word.startswith('+') and word[1:].isalpha():
            return 0.73
        if '(' in token or ']' in token:
            return 0.67
        return 0.55
    if word and all('\u0400' <= c <= '\u052f' for c in word):
        if not uk:
            return 0.06 if space and word == 'в' else 0.01
        if len(word) > 4:
            return 0.20
        if word == 'в':
            return 1.99 if space else 0.50
        if 'и' in word and len(word) <= 3:
            if word.startswith('к'):
                return 0.79
            if word == 'и' and space:
                return 0.23
            if word.endswith(('и', 'ий')):
                return 1.66
            if word.endswith(('ис', 'ив', 'им')):
                return 1.47
            return 0.85
        if len(word) >= 2 and word.endswith('в'):
            return 0.95
        if word.endswith(('ня', 'ля', 'тя', 'лю', 'ню')) or word == 'н':
            return -0.63
        if word.endswith(('ь', 'ж')):
            return -0.31
        if space and word in ('б', 'д', 'м', 'ц', 'об', 'до'):
            return 0.87
        if not space and word.endswith(('й', 'х', 'ц')):
            return 0.45
        return 0.30 if space and len(word) <= 3 else 0.06
    if any('\u0600' <= c <= '\u06ff' for c in word):
        if word == 'ی':
            return 0.83
        if word == 'و':
            return (1.52 if fa else 0.16) if space else (0.85 if fa else 0.10)
        if fa and len(word) <= 3:
            if word in ('گ', 'چ', 'به', 'در'):
                return -0.33
            if word.endswith(('ان', 'ین', 'ید', 'ود', 'یر')):
                return 0.59
            if space and len(word) == 1:
