    if word == 'de' and space:
        return 1.35 if ro else 0.76 if nl else 0.02
    if ro and len(word) <= 4:
        if word == 'î':
            return 2.3
        if word in ('ț', 'ţ'):
            return -0.44
        # Relative pronouns, auxiliaries, and other grammatical words.
        if word in ('care', 'ce'):
            return 1.1
        if word in ('au', 'fi', 'fost', 'vor'):
            return 0.8
        if word in ('și', 'şi', 'si', 'în', 'ei', 'lei', 'dar'):
            return 1.17
        # Plural/personal endings versus definite-article endings.
        if word.endswith('i'):
            if word.endswith(('ți', 'ţi', 'ii')):
                return 1.1
            return 0.45 if len(word) <= 2 else 0.19
        if word.endswith(('ul', 'le', 'ile', 'area')):
            return -0.46
    if space and word in ('si', 'en'):
        return 0.29 if word == 'si' else 0.12
    if word == '[string':
        return 0.37
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    ages = (0, 0, 0, 0) if carry is None or carry[0] != doc else carry[1]
    cues = (any(c in UKRAINIAN for c in token),
            any(c in PERSIAN for c in token),
            any(c in ROMANIAN for c in token) or word in RO_WORDS,
            word in NL_WORDS)
    ages = tuple(64 if cue else max(0, age - 1)
                 for age, cue in zip(ages, cues))
    return (doc, ages), float(response(token, *ages))

