programs.sol:
"""Partial lexical/formatting approximation, not a unified topic detector.

Recognize explicit word families and several isolated strong lexical responses;
otherwise use small punctuation, script, and spelling-pattern offsets. Track
message roles and tool calls to distinguish their endings. A few phrase endings
and timestamped author credits get contextual corrections. Reset at document
boundaries. Most vocabulary-specific and longer-context behavior is omitted.
"""

import re

READS = ()

# Familiar English lemmas and their inflections share an approximate response.
FAMILIES = (
    ('know knows knew knowing known', -0.070),
    ('work works worked working worker workers', -0.055),
    ('expect expects expected expecting unexpected', -0.068),
    ('make makes made making', 0.052),
    ('do does did done', 0.045),
    ('const constant constants', -0.080),
    ('problem problems', -0.048),
    ('length lengths height heights depth depths size sizes', 0.053),
    ('maximum minimum maximal minimal', -0.058),
    ('above below', 0.060),
    ('both several', 0.050),
    ('any some either', 0.022),
    ('all every', -0.013),
    ('between among', 0.050),
)
WORDS = {word: value for forms, value in FAMILIES for word in forms.split()}
WORDS.update({
    'integrity': 0.43, 'egrity': 0.43,  # whole word and ending fragment
    'guinness': 0.60,                 # the Guinness name
    '江湖': 0.66,                      # martial/social world
    '办案': 0.66,                      # handling a legal case
    '진행': 0.56,                      # Korean: proceeding/progress
    'pantry': -0.60,
    'hmm': -0.12,
    'today': 0.14,
    'purpose': 0.085, 'purposes': 0.22,
    'half': -0.10, 'each': -0.043,
    'which': -0.026, 'without': -0.050,
})
# These are specific programming names, not all buffers or all Java code.
PROGRAMMING_NAMES = {
    'VertexBuffer': -0.70,
    '.ByteArray': -0.73,
    '.ObjectMapper': -0.86,
    '.databind': 0.61,
    'onCreateViewHolder': 0.63,
    '/epl': 0.77,  # Eclipse Public License URL path
    '#+#': -0.52,  # decorative source-header marker
}
PUNCTUATION = {'/': 0.027, '*': 0.033, '-': 0.013, '”': 0.055}
DELIMITERS = {
    '<think>': -0.133, '</think>': -0.090,
    '<tool_call>': -0.037, '</tool_call>': 0.027,
    '<tool_response>': -0.176, '</tool_response>': 0.081,
}


def lexical_value(text):
    spelling = text.strip()
    word = spelling.lower()
    if spelling in PROGRAMMING_NAMES:
        return PROGRAMMING_NAMES[spelling]
    if word == 'служ':  # Russian service-related stem
        return 0.37 if text.startswith(' ') else 0.49
    if word in WORDS:
        return WORDS[word]
    if word in PUNCTUATION:
        return PUNCTUATION[word]
    if '\u00a0' in text:
        return 0.024
    if '\ufffd' in text:
        return 0.025
    if any('\uac00' <= c <= '\ud7af' for c in word):  # Hangul
        return 0.020
    if any('\u3040' <= c <= '\u309f' for c in word):  # Hiragana
        return 0.013
    if word in ('.py', '.java', '.js', '.h', '.c'):
        return 0.045  # source-file extensions
    if word in ('.html', '.json', '.xml', '.md'):
        return -0.025  # markup, data, documentation extensions
    value = 0.0015
    if word.isascii() and word.isalpha():
        for affix, minimum, offset, ending in (
            ('ly', 5, -0.016, True),
            ('dis', 6, -0.015, False),
            ('un', 5, 0.014, False),
            ('sub', 6, 0.033, False),
            ('under', 8, -0.023, False),
        ):
            matches = word.endswith(affix) if ending else word.startswith(affix)
            if len(word) > minimum and matches:
                value += offset
    if spelling.endswith('Test'):
        value -= 0.026
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    if carry is None or carry[0] != document:
        role, awaiting_role, tool_call, previous, tail = '', False, False, '', ''
    else:
        _, role, awaiting_role, tool_call, previous, tail = carry
    if awaiting_role:
        role, awaiting_role = text.strip(), False

    if text == '<|im_start|>':
        awaiting_role, tool_call, value = True, False, -0.034
    elif text == '<|im_end|>':
        value = -0.153 if tool_call else {
            'assistant': -0.015, 'user': -0.041,
        }.get(role, -0.070)
        tool_call = False
    elif text == '<|endoftext|>':
        value, role, awaiting_role, tool_call = -0.020, '', False, False
    elif text in DELIMITERS:
        value = DELIMITERS[text]
        if text == '<tool_call>':
            tool_call = True
    elif word == 'integrity' and previous == 'academic':
        value = 0.60  # the academic-integrity phrase in the harvest
    elif word == 'by' and re.search(r'\d{2}:\d{2}:\d{2}\s*$', tail):
        value = -0.60  # author credit following a timestamp
    elif word == 'the' and previous == 'all':
        value = -0.085
    elif word == 'to' and previous in ('easy', 'difficult', 'looking'):
        value = 0.080
    elif word == 'of' and previous in ('lot', 'bit', 'amount', 'variety'):
        value = 0.070
    elif word == 'of' and previous == 'instead':
        value = -0.095
    else:
        value = lexical_value(text)
    state = (document, role, awaiting_role, tool_call, word, (tail + text)[-40:])
    return state, float(value)

