"""A conservative lexical proxy for the component's clearest recurrent theme:
heart and circulation terms.  It recognizes a short list of anatomy and
clinical words, including when tokenized in pieces, and predicts a small
positive activation only for those words.  It does not infer medical context.
"""
READS = ()
HEART_AND_CIRCULATION = {
    "heart", "blood", "stroke", "circulation", "cardio", "pressure",
    "systolic", "liver", "shock", "angiography", "gallbladder",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, history = carry if carry is not None else (doc, "")
    if doc != old_doc:
        history = ""
    text = (history + prefix.token_strings[-1]).lower()
    word = ""
    for char in reversed(text):
        if char.isalpha():
            word = char + word
        elif word:
            break
    hit = word in HEART_AND_CIRCULATION
    return (doc, text[-80:]), (0.25 if hit else 0.0)

programs.sol:
"""A quotation-boundary detector, favoring quotes inside prose phrases.
Double quotes after ordinary words, determiners, and prepositions are strongest.
Opening quotes after sentence punctuation are weaker. Programming operators,
field-value syntax, and code-like identifiers suppress ordinary string quotes.
Comma-before-quote and period-before-quote have their own closing strengths;
quotes followed by punctuation or merged with letters are mostly ignored.
Only a short text tail is retained, and it resets at document boundaries.
"""
import re

READS = ()
DETERMINERS = set(
    'a an the this that these those any each every some such '
    'its their my your his her our all both another either neither'.split()
)
PREPOSITIONS = set(
    'of in on to for from as by into under over about with without'.split()
)
CODE_WORDS = set(
    'return echo case require import printf print cout println '
    'assert elif else typeof default'.split()
)
OPEN_QUOTES = set('“„‘«「')
CLOSE_QUOTES = set('”’»」')
QUOTES = OPEN_QUOTES | CLOSE_QUOTES | set('"\'')


def quotation(token, tail):
    if not token or token[-1] not in QUOTES:
        return 0.001
    mark, before = token[-1], token.strip()[:-1]
    p = tail.rstrip()
    match = re.search(r'[\w-]+$', p)
    word = match[0].lower() if match else ''
    last = p[-1:] or '\n'
    line = re.sub(r'<\|.*?\|>', '', tail.split('\n')[-1])
    operator = (last in '=+<>{[(&|\\' or '_' in word
                or word in CODE_WORDS or line.strip() == 'if'
                or (last in ':,' and p[-2:-1] in {'"', "'", '}', ']'}))
    code = (operator or any(c in line for c in '={}')
            or bool(re.search(r'[a-z_][_.][a-z_]|<<|\w+\([^)]*$', line)))
    # Punctuation attached before the mark changes the boundary type.
    if before == '(':
        return (1.0 if mark == '“' else 0.65) if token.startswith(' ') else 0.0
    if any(c.isalnum() for c in before):
        return -0.025
    if before in {',', ",'"}:
        return (1.25 if mark in '"”' else 0.55) * (0.2 if code else 1.0)
    if before in '.!?。！？' and before:
        if before == '。':
            return 0.23
        return 0.65 if before == '.' else 0.36
    if before and before not in {'、', '，', '-'}:
        return 0.02
    opening = mark in OPEN_QUOTES or (
        token.startswith(' ') and mark not in CLOSE_QUOTES
    )
    if opening:
        # Larger responses within phrases; smaller at sentence boundaries.
        spaced = token.startswith(' ')
        strength = {'"': 1.2, "'": 0.5, '“': 1.4 if spaced else 0.83,
                    '„': 0.55 if spaced else 0.83, '‘': 0.75 if spaced else 0.5,
                    '«': 0.62 if spaced else 0.4, '「': 0.55}.get(mark, 0.6)
        if not p:
            return 0.13
        if mark in '"\'' and (operator or p.endswith('#include')
                              or re.search(r'\((?:command|load|open|print|write-line)$', p)):
            return -0.055
        if word:
            value = strength
            if word in DETERMINERS:
                value += 0.35
            elif word in PREPOSITIONS:
                value += 0.12
            if word.isdigit():
                value *= 0.2
            if code and mark in '"\'':
                value *= 0.35
        else:
            boundary_factor = (0.45 if last in '.!?,:;。！？'
                               else 0.65 if last in '–—&' else 0.2)
            value = strength * boundary_factor
        return value * (0.6 if before in {'、', '，'} else 1.0)
    # Unprefixed straight marks and typographic closing marks.
    if not p:
        return 0.15
    if mark == '"':
        if tail[-1:].isspace():
            return 0.25
        value = 0.35 if code else 0.83
    elif mark == '”':
        value = 0.2 if '\u4e00' <= p[-1] <= '\u9fff' else 0.72
    else:
        value = {'»': 0.2, "'": 0.05, '’': 0.05}.get(mark, 0.0)
    return value if word else value * 0.5


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, (tail + token)[-160:]), float(quotation(token, tail))

