DOUBLE_QUOTES = frozenset('"“”„‟«»‹›「」『』〝〞＂')


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    for i, char in enumerate(token):
        if char not in DOUBLE_QUOTES:
            continue
        before = token[i - 1] if i else ""
        after = token[i + 1] if i + 1 < len(token) else ""
