programs.sol:
"""Estimate local article/comparison constructions, ignoring most text.

Indefinite articles in 'as a/an' are strongly positive; predicative articles
elsewhere are weaker positives. Subject pronouns and passive descriptions
after 'as' are negative. Fixed comparisons ('as well', 'as possible', etc.)
have their own strengths. 'Like' and 'than' give weaker related responses.
Some French, German, Spanish and Portuguese equivalents also respond.
Remember two tokens, resetting at document boundaries.
"""
READS = ()

# Fixed 'as ...' constructions, indexed by their next word.
AS_PHRASES = {
    'well': 1.6, 'possible': 3.5, 'part': 2.35, 'one': 2.3,
    'being': 1.0, 'follows': 1.0, 'far': 0.8, 'long': 0.6,
    'to': 0.35, 'much': -0.85, 'many': -1.0, 'the': -0.3,
    'if': -1.3, 'though': -1.6, 'before': -1.7, 'ever': -2.5,
    'in': -1.5, 'per': -1.5, 'with': -1.8, 'at': -1.7, 'on': -1.4,
    'when': -1.45, 'where': -0.9, 'here': -1.9, 'under': -2.2,
    'already': -2.2, 'previously': -2.2,
    'such': 0.8, 'either': 0.8, 'another': 1.8, 'something': 1.9,
    'shown': -1.0, 'known': -1.0, 'given': -0.75, 'said': -2.7,
    'what': -1.8, 'saying': 1.7, 'early': 0.45, 'always': -1.4,
}
COMPARISON_WORDS = {'comme', 'como', 'als', 'wie'}
INDEFINITE_ARTICLES = set('''a an un une una um uma
    ein eine einer einen einem eines'''.split())
OPENING_PUNCTUATION = "\"'“‘([—"

RELATIONAL_NOUNS = set('''result consequence function whole example reference
    way means part member matter basis guide'''.split())


def article_after(word):
    if word in {'is', 'was', 'be', 'being', 'been', 'were'}:
        return 0.8
    if word in {'are', 'am', "'s", '’s'}:
        return 0.4
    if word in {'become', 'became', 'becomes', 'becoming', 'just', 'merely'}:
        return 1.9
    if word in {'not', 'like', 'than', 'called', 'simply', 'actually'}:
        return 1.5
    if word in {'or', 'only', 'also', 'quite', 'still', 'really', 'even',
                'always', 'either', 'remains', 'constitutes', "'t", '’t'}:
        return 0.8
    if word in {'into', 'from', 'provide', 'provides', 'represent', 'represents'}:
        return 0.4
    if word in {'to', 'by', 'at'}:
        return 0.2
    if word in {'in', 'for', 'with', ','}:
        return -0.1
    if word in {'on', 'during'}:
        return -0.25
    return 0.0


def after_as(word):
    if word in {'it', 'there'}:
        return -3.0
    if word in {'we', 'they'}:
        return -2.8
    if word in {'he', 'she'}:
        return -2.2
    if word in {'i', 'you', 'this', 'these', 'that'}:
        return -1.8
    if word in {'those', 'your', 'their', 'its', 'his', 'her', 'our', 'my'}:
        return -0.65
    if word in {'is', 'are', 'do', 'should', 'would', 'could'}:
        return -2.2
    if word in {'was', 'were', 'did', 'does', 'will', 'needed', 'seen',
                'done', 'discussed'}:
        return -2.9
    if word in {'can', 'may', 'must'}:
        return -1.3
    if word in {'described', 'compared', 'noted', 'mentioned', 'illustrated',
                'observed', 'used'}:
        return -1.95
    if word in AS_PHRASES:
        return AS_PHRASES[word]
    if len(word) > 4 and word.endswith('ed'):
        return -1.1  # Passive descriptions, as in 'as specified'.
    if len(word) > 4 and word.endswith('ly'):
        return -0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    _, prev, before, raw = (carry if carry and carry[0] == doc
                            else (doc, '', '', ''))
    token = prefix.token_strings[-1]
    word = token.strip().lstrip(OPENING_PUNCTUATION).lower()
    value = 0.0
    if (prev in COMPARISON_WORDS and word in INDEFINITE_ARTICLES
            and token[:1].isspace()):
        value = 1.5 if word in {'une', 'una', 'uma', 'eine'} else 1.2
    elif token.strip() in {'a', 'an'} and token[:1].isspace():
        if prev == 'as':
            value = 5.5 if word == 'a' else 6.05
            value += 0.2 if raw.strip() == 'As' else 0.0
            if before == 'such':
                value -= 2.5
            elif before == 'well':
                value -= 1.3
            value -= 2.0 if raw == 'as' else 0.0
        else:
            value = article_after(prev)
            value += 0.17 if word == 'an' and value > 0.0 else 0.0
    elif prev in {'as', 'like', 'than'}:
        scale = {'as': 1.0, 'like': 0.5, 'than': 0.8}[prev]
        value = scale * after_as(word)
        if prev == 'as' and (not word or token.strip() in {'"', '“'}):
            value = 0.45
        if prev == 'like' and word in {'this', 'that'}:
            value = -1.18
        if prev == 'than':
            value = {'the': -0.54, 'one': 0.79, 'or': -1.28}.get(word, value)
    elif before == 'as' and prev == 'part' and word == 'of':
        value = 1.0
    elif before == 'as' and prev in {'a', 'an'}:
        if word in RELATIONAL_NOUNS:
            value = 1.25
        elif word.isalpha():
            value = 0.15
    # Do not mistake unspaced lowercase word-pieces for function words.
    if token[:1].islower() and raw[-1:].isalpha():
        word = ''
    return (doc, word, prev, token), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:1369: the article that follows "as" (or "than").

The component is close to a bigram detector on (previous word, this word).
Its activation is large only on a few words, and each rule below says how
large and why:

  * "a" / "an" right after "as" or "As" ("as a", "regarded as an"):
    strongly positive, about +5.5. After "such as" it is weaker, about +3.
  * "possible", "part", "one", "something", "well", "follows" right after
    "as": positive, about +1 to +3.5 ("as possible" is the largest).
  * a pronoun ("it", "we", "they", "I", ...) or a past participle
    ("described", "shown") right after "as", or a pronoun after "than":
    negative, about -2 to -2.5 ("as it", "as they", "as described").
  * "a" / "an" after a verb of becoming ("become", "became") or after
    "not", "just", "like", "than": about +1.8.
  * "a" / "an" after "is", "was", "be", "been", "are", "really", "also"...:
    about +0.8.
  * any other word, or "a" / "an" after a preposition: about 0.

Activation is in the units of the component's own contribution to the
residual stream; the signs are as measured.
"""

READS = ()

ARTICLES = {"a", "an"}
PRONOUNS = {"it", "we", "they", "she", "he", "i", "you", "there", "this", "these", "that",
            "is", "was", "were", "are", "those", "my", "his", "her", "its", "our", "their", "your"}
AS_POSITIVE = {"possible": 3.5, "part": 2.3, "one": 2.1, "well": 1.6, "follows": 1.0,
               "something": 1.9, "such": 0.8, "far": 0.9}
BECOMING = {"become", "becomes", "became", "becoming", "just", "like", "not", "than"}
COPULA = {"is", "was", "be", "been", "being", "were", "are", "am", "really", "still",
          "even", "quite", "only", "also", "actually"}
AS_NEGATIVE_WORDS = {"if", "when", "in", "at", "before", "with", "on", "necessary"}


def _word(prefix, back):
    """The word `back` tokens before the newest one, or "" across a document break."""
    i = len(prefix.token_ids) - 1 - back
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i].strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix, 0)
    prev = _word(prefix, 1)
    if prev == "as":
        if word in ARTICLES:
            return carry, 3.0 if _word(prefix, 2) == "such" else 5.5
        if word in AS_POSITIVE:
            return carry, AS_POSITIVE[word]
        if word in PRONOUNS or word.endswith("ed") or word in AS_NEGATIVE_WORDS:
            return carry, -2.0
        return carry, 0.0
    if prev == "than":
        if word in ARTICLES:
            return carry, 1.9
        if word in PRONOUNS:
            return carry, -2.2
        return carry, 0.0
    if word in ARTICLES:
        if prev in BECOMING:
            return carry, 1.8
        if prev in COPULA:
            return carry, 0.8
    return carry, 0.0

programs.sol:
"""A lexical width signal, not a measurement of numerical dimensions.

Width words and code properties give large positive responses; related
breadth and dimension terms respond more weakly. This token-local rule
captures the sparse width spikes, not the many small token-specific effects.
"""
READS = ()

BREADTH_WORDS = {'wide', 'wider', 'widest', 'widen', 'widened', 'widening', 'breadth'}
LAYOUT_TERMS = {'figsize': 0.60, 'cellpadding': 0.50,
                'addgap': 0.85, 'addcontainergap': 0.85}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lstrip('._-(,;*').lower()
    spaced = token[:1].isspace()
    value = -0.0014
    if word in {'width', 'widths'}:
        value = 0.92 if spaced else 1.14
        if text.startswith('.'):
            value = 1.50 if text[1:].islower() else 1.02
        elif text.startswith(('_', '-')):
            value = 1.12
        elif text.startswith(('(', ',')):
            value = 0.80
        elif text.startswith((';', '*')):
