    value = 0.0
    if word.startswith("х"):
        value = 0.45
    elif plain and plain[0].lower() == "h":
        spaced = token[:1].isspace()
        if word == "he":
            value = 0.22 if token == " he" else 0.55
        elif word == "her":
            value = 0.25
        elif word in PRONOUNS | AUXILIARIES | ADVERBS:
            value = 0.5 if token == "had" else 0.0
        elif word == "h":
            value = 1.4 if spaced else (1.1 if piece == "H" else 0.65)
        elif word in {"hour", "hours"}:
            value = 1.25
        elif piece[0] not in "hH":
            value = 0.5
        else:
