    '<<<<': -4.9, '>>>>': -1.17, '<<=': -3.4,
    '==': -1.38, '===': -1.25, '!=': -0.84, '!==': -0.84,
    '<': -0.53, '>': -0.1, '<=': -1.14, '>=': -0.77,
    '<>': -0.62, '=<': -0.78, '<-': -0.84, '=>': -0.58,
    '|': -0.28, '><': -0.37, '«': -1.18, '»': -0.23,
    '≤': -0.65, '≥': -0.52, '≠': -0.38, '≈': -0.42,
    '≡': -0.45, '⇒': -0.54, '→': -0.08, '←': -0.82,
    '≫': -1.2, '⟨': -0.87,
