    doc = prefix.document_ids[-1]
    previous, recent = carry[1:] if carry and carry[0] == doc else ('', '')
    token = prefix.token_strings[-1]
    s = token.strip()
    spaced = token.startswith(' ')
    value = SIGNS.get(s, 0.0)
    if spaced:
        value = SPACED.get(s, value)

    if s not in SIGNS:
        if '<<' in s and len(s) < 7:
            quoted = '"' in s or "'" in s
            if s.startswith('<<') and quoted:
                value = -2.8
            elif quoted:
                value = -4.7 if spaced else -4.1
            else:
                value = -5.3
        elif s and set(s) == {'='} and 4 <= len(s) <= 11:
            value = -0.7 if '\n' not in token else 0.0
        elif '|' in s and '||' not in s and len(s) < 5:
            value = -0.55 if s.endswith('|\\') else -0.42
        elif '<' in s and len(s) < 5:
            if not any(c.isalnum() for c in s) and '/' not in s and '!' not in s:
                value = -0.45
        elif s.endswith('==') and len(s) < 7:
            if not any(c.isalnum() for c in s):
