"""Detect short ut spellings, especially 'but', cut- and mut-.

The strongest responses are on short words or fragments; leading spaces
usually weaken them. This is not purely a meaning-of-'but' detector, though
some contrast words and Chinese cutting/mutuality words respond too. Unmodelled
lexical and contextual variation is left at zero.
"""
import math
import string

READS = ()

UT_STEMS = {
    'ut': 5.1, 'mut': 5.3, 'nut': 5.0, 'cut': 4.4,
    'gut': 3.7, 'hut': 5.2, 'rut': 4.1, 'shut': 4.8,
    'put': 2.1, 'aut': 2.7, 'fut': 3.1, 'tut': 2.5,
}
CONTRAST = {
    'however': 0.8, 'mais': 0.7, 'pero': 0.9, 'но': 1.5,
    '但': 1.5, '但是': 1.1, 'ですが': 0.7, 'けど': 0.65,
    '지만': 1.0, 'sondern': 0.8, 'nhưng': 0.9, 'aber': 0.45,
}

# Specific Chinese words: mutual, mutually (two orders), cut.
RELATED_WORDS = {'互': 3.2, '互相': 1.6, '相互': 0.9, '割': 1.7}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    raw = token.strip().strip(string.punctuation + '—')
    word = raw.lower()
    spaced = token[:1].isspace()
    value = 0.0
    if word == 'but':
        value = 2.32 if spaced and raw != 'But' else 2.9
    elif word in UT_STEMS:
        value = UT_STEMS[word]
        if spaced:
            value *= 0.74 if word in ('ut', 'put') else 0.83
    elif word.startswith('ut'):
        if word == 'uts':
            value = 4.5
        elif word.startswith('utting'):
            value = 4.5
        elif word.startswith('utter'):
            value = 2.8
        elif word.startswith(('util', 'utf')):
            value = 0.15
        elif word == 'utc':
            value = 0.95
        else:
            value = 2.6 * math.exp(-0.45 * max(0, len(word) - 3))
            if word in ('uta', 'uto', 'uty'):
                value = 1.6
        if spaced and word != 'utc':
            value *= 0.65
    elif word.startswith('mutual'):
        value = 3.65
    elif word.startswith(('mutat', 'mutant')):
        value = 2.0
    elif word.startswith('cutt') or word == 'cuts':
        value = 3.4 if len(word) <= 7 else 1.0
    elif word.startswith(('shutt', 'nuts')):
        value = 2.4
    elif word.startswith(('put', 'butter', 'gutter')):
        value = 1.3
    elif 'ut' in word and 'out' not in word:
        value = 0.15
        if word.endswith('ut') and len(word) <= 4:
            # Vowels immediately before ut soften longer short spellings.
            value = 0.45 if len(word) == 4 and word[-3] in 'aeiou' else 2.1
    elif word in CONTRAST and (spaced or word != 'но'):
        value = CONTRAST[word]
        if raw == 'however':
            value = 0.25
    elif word in RELATED_WORDS:
        value = RELATED_WORDS[word]
    elif word in ('ут', 'üt'):
        value = 2.35 if word == 'ут' else 1.5
    return None, value

