"""Fires on the English contrast word "but" and on short words built around the
syllable "-ut" (cut, nut, mut, gut, shut, put, ute, utter, ...).

It is a token-level detector: it looks only at the current token's spelling, with no
memory across the document. Strength is graded by how strongly the model's layer-0
MLP responds to each family: "-cut"-like words (cut, nut, mut, gut, shut, rut, bare "ut")
are the strongest, "but" is medium, "put" and other "-ut" words are weaker, and the
multilingual contrast words ("however", "mais", "但", "но", ...) are faint.
"""
import re

READS = ()

# a short word ending in "ut": up to two leading consonants, optional -s/-e/-ed/-ter/-ting ending
UT_WORD = re.compile(r"^[bcdfghjklmnpqrstvwxz]{0,2}ut(s|e|ed|ter|ting)?$")
STRONG = {"ut", "uts", "cut", "cuts", "cutting", "nut", "mut", "gut", "shut", "rut"}
CONTRAST = {"however", "mais", "但", "但是", "nhưng", "но", "しかし", "ですが"}


def step(carry, prefix, upstream):
    w = prefix.token_strings[-1].strip().lower()
    if w == "but":
        value = 2.5
    elif w in STRONG:
        value = 4.0
    elif UT_WORD.match(w):
        value = 1.8
    elif w in CONTRAST:
        value = 0.6
    else:
        value = 0.0
    return carry, float(value)

