"""Fires on the noun for a brief moment. Strongest on 'moment' and 'instant' (and their
translations and subword pieces), then on 'of' right after them ('a moment of'); weaker on
other short-time words ('seconds', 'minutes', 'immediately', 'now', 'soon', 'after',
'at the same time').

The program tracks the word being spelled across tokens (`carry`), so a word split into
pieces, like 'inst' + 'ant', is read as one word."""

import re

READS = ()

MOMENT = {"moment", "moments", "instant", "instants", "instantly", "instantaneous",
          "instantaneously", "momento", "momenti", "momentos"}
MOMENT_CJK = ("刻", "瞬")
SHORT_SPAN = {"immediately", "immediate", "minute", "minutes", "second", "seconds", "hour",
              "hours", "sudden", "suddenly"}
SHORT_SPAN_CJK = ("立即", "突然")
NOW = {"now"}
SOON = {"soon", "once", "after", "later", "today", "tonight", "morning", "afternoon",
       "night", "yesterday", "day"}


def is_piece(word):
    """A word part that could grow into a moment word, e.g. 'inst' or 'mome'."""
    return len(word) >= 4 and any(m.startswith(word) for m in MOMENT)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    # The word so far: the previous word's letters continue if this token has no leading space.
    run = ((carry or "") if token[:1].isalpha() else "") + token.lower()
    word = re.search(r"[a-z]*$", run).group(0)
    if word in MOMENT or any(c in token for c in MOMENT_CJK):
        value = 5.5
    elif word == "of" and prev in MOMENT:
        value = 4.0
    elif word in SHORT_SPAN or any(c in token for c in SHORT_SPAN_CJK):
        value = 1.0
    elif word in NOW:
        value = 1.2
    elif word in SOON or (word == "time" and prev == "same"):
        value = 0.6
    elif is_piece(word):
        value = 1.0
    else:
        value = 0.0
    return word, value

