    "elements", "factor", "factors", "term", "terms", "matter", "issue", "issues", "problem",
    "problems", "question", "lot", "out", "much", "plenty", "multiple", "quality", "lack",
    "loss", "species", "genus", "unit", "units", "standard", "standards", "rights", "power",
    "powers", "cup", "cups", "majority", "couple",
}

NEUTRAL = {
    "number", "numbers", "part", "parts", "one", "some", "instance", "kind", "type", "side",
    "sides", "amount", "value", "result", "results", "percent", "sum", "form", "manner",
    "length", "portion", "combination", "period", "version", "either", "any", "none",
}

MILD_NEG = {
