    "thought", "thinking", "look", "list", "range", "array", "grid", "matrix", "graph",
    "map", "vector", "sequence", "sequences", "distribution", "distributions", "probability",
    "likelihood", "frequency", "frequencies", "subset", "subsets", "permutation",
    "permutations", "arrangement", "structure", "landscape", "trajectory", "interval",
    "curve", "spectrum", "data", "information", "overview", "outline", "perspective",
    "extent", "evolution", "complexity", "existence", "occurrence", "efficiency", "accuracy",
    "prevalence", "behavior", "location", "framework", "variability",
}


def _is_of(token):
    return token.strip().lower() == "of"


def _strength(word):
    """How strongly `word` followed by " of" drives the component (about -1 to 1); a word
    not listed above gets the typical value of 0.15."""
    if word in TECHNICAL:
        return -1.0
    if word in MILD_NEG:
        return -0.35
    if word in NEUTRAL:
        return 0.0
    if word in PEOPLE or (len(word) > 4 and word.endswith(("er", "ers", "or", "ors"))):
