"""Visual separators: pipes, horizontal rules and wide whitespace.

Hyphen rules respond most strongly; other repeated punctuation is weaker.
Pipes weaken with earlier pipes in the same document and line. Rule endings
can occupy a separate token. Ordinary words are approximated by zero.
"""
import math
import re

READS = ()
RUN = re.compile(r'(-{2,}|={3,}|_{3,}|\.{4,}|\*{3,}|#{4,}|~{4,}|/{4,})')
# Character: minimum length, initial response, gain, maximum extra length.
CURVES = {
    '=': (4, 1.17, 0.11, 8),
    '_': (3, 0.39, 0.057, 17),
    '.': (4, 0.11, 0.14, 6),
    '*': (3, 0.35, 0.29, 5),
    '#': (4, 0.11, 0.15, 12),
    '~': (4, 0.56, 0.10, 12),
    '/': (4, 0.34, 0.10, 16),
}
LINE_GLYPHS = {'ـ': 1.0, 'ー': 0.28, '¯': 0.45, '─': 0.45}


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, '', 0.0)
    _, pipes, line_pipes, last_char, last_strength = carry
    text, nl = token.strip(), token.count('\n')
    pad = token.startswith(' ')
    punctuation = not any(c.isalnum() for c in text)
    pipe = punctuation and '|' in text and text != '|='
    run = RUN.search(text) if punctuation else None
    value = 0.0
    if not text:
        spaces = token.count(' ')
        value = min(0.75, 0.035 + 0.023 * spaces) if nl and spaces >= 2 else 0.0
        if not nl and spaces >= 32:
            value = 0.24
        if token == '\x0c':
            value = 0.62
    elif text[0] in LINE_GLYPHS and set(text) == {text[0]}:
        value = LINE_GLYPHS[text[0]]
    elif punctuation and any(c in text for c in '│∣'):
        value = 0.4
    elif pipe:
        value = 0.62
        if '||' not in text:
            value = 0.83 - 0.04 * pad - 0.19 * bool(nl)
            value -= 0.24 * pipes / (pipes + 3) + 0.04 * min(line_pipes, 3)
    elif run:
        char, n = run[0][0], len(run[0])
        if char == '-':
            if n <= 3:
                value = 0.76 - 0.1 * pad if n == 2 else 2.03 - 0.2 * pad
                value += 0.25 * bool(nl) if n == 2 else -0.5 * min(nl, 2)
            else:
                value = 2.85 + 0.3 * min(n - 4, 5) + 0.57 * pad
                value -= 0.24 * bool(nl) + 1.17 * (nl >= 2) + 0.38 * (n >= 48)
            if '<!' in text:
                value = 0.28
            elif '*' in text or text.startswith('//'):
                value *= 0.6
        elif char == '=' and n == 3:
            value = 0.035 if pad else 0.28
        else:
            minimum, base, gain, cap = CURVES[char]
            value = base + gain * min(n - minimum, cap) - 0.25 * (n >= 48)
            if char == '_':
                value += -0.25 * pad + 0.31 * min(nl, 2)
            if char == '#':
                value += 0.74 * bool(nl)
            if text.startswith('#') and char == '=':
                value *= 0.55
    elif punctuation and len(text) >= 3 and '-' in text and set(text) <= set('-*+'):
        value = 1.2
    elif text in ('&&', '++', '+++'):
        value = {'&&': 0.29, '++': 0.15, '+++': 0.33}[text]
    if last_char == '-' and last_strength > 2 and text in ('-', '--', '---'):
        value += (0.95 * math.exp(-0.5 * nl) if len(text) == 2
                  else 0.9 if len(text) == 1 else 0.35)
    if last_strength and token in ('\n', '\n\n', '\r\n', '\n\n\n\n'):
        factor = 0.35 if '\r' in token else 0.23 if last_char == '-' else 0.14
        value = factor * last_strength * math.exp(-0.45 * (nl - 1))
    rule = run and len(run[0]) >= 4 and text.endswith(run[0]) and not nl
    last_char, last_strength = (run[0][0], value) if rule else ('', 0.0)
    pipes += int(pipe)
    line_pipes = 0 if nl else line_pipes + int(pipe)
    return (doc, pipes, line_pipes, last_char, last_strength), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:1378 -- a "divider line / table border" detector.

What it responds to: visual separator text, the kind a person sees as a rule or a
table border. Long runs of dashes ("-----") fire hardest: a dash run of about 16 or
more is about 4.5 (a markdown horizontal rule or an ASCII table border), and short
runs fire less ("--" about 1, "---" about 2). Runs of "=", "*", "_", "/", "#", "." fire
only when long (6+ characters) and more weakly. Table pipes ("|", " |", "||") fire
moderately (about 0.6). Lines of indentation spaces ending in a newline fire weakly,
rising with length. Everything else, including ordinary words and punctuation,
predicts 0.

The program looks only at the newest token, via its decoded string. It has no state.
"""

READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    s = raw.strip()

    # Indentation-only tokens that end a line, e.g. "            \n".
    if not s:
        if "\n" in raw and len(raw) >= 10:
            return carry, min(0.7, 0.04 * (len(raw) - 8))
        return carry, 0.0

    # Table pipes: "|", " |", "||", "(|", "|\\".
    if set(s) <= set("|()\\"):
        return carry, 0.6 if "|" in s else 0.0

    # Runs of one repeated symbol.
    if len(s) >= 2 and len(set(s)) == 1:
        n = len(s)
        if s[0] == "-":
            # Dash runs: "--" ~1, "---" ~2, 6 dashes ~3.7, 16+ dashes ~4.5 (capped).
            return carry, min(4.5, 1.0 + 0.75 * (n - 2))
        if s[0] in "=*_/#.~" and n >= 6:
            # Other rule characters: ramps up with length, capped at 2.2.
            return carry, min(2.2, 0.3 * (n - 3))

    return carry, 0.0

programs.luna:
"""Estimate the component's response to visible text separators.

It gives a positive pulse to runs of bars, dashes, dots, equals signs,
underscores, and hashes, with longer runs receiving larger pulses. It also
marks the Japanese transition word さて. All ordinary text is predicted as
zero; the rule captures the component's conspicuous formatting-boundary
responses, not its small context-dependent fluctuations.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    s = token.strip()
    if not s:
        return None, 0.0

    # Repeated punctuation is a concise cue for visual separators and rules.
    if all(ch == "|" for ch in s):
        return None, min(0.95, 0.55 + 0.08 * len(s))
    if all(ch == "-" for ch in s):
        if len(s) < 2:
            return None, 0.0
        return None, min(5.0, 0.55 + 0.16 * len(s))
    if all(ch == "." for ch in s):
        if len(s) < 4:
            return None, 0.0
        return None, min(1.1, 0.12 + 0.045 * len(s))
    if all(ch == "=" for ch in s):
        if len(s) < 3:
            return None, 0.0
        return None, min(2.2, 0.35 + 0.04 * len(s))
    if all(ch == "_" for ch in s):
        if len(s) < 3:
            return None, 0.0
        return None, min(1.0, 0.25 + 0.045 * len(s))
    if all(ch == "#" for ch in s):
        if len(s) < 3:
            return None, 0.0
        return None, min(1.0, 0.2 + 0.04 * len(s))

    # Mixed punctuation separators, including chapter-style .-- markers.
    if s in (".--", "(--", "('--"):
        return None, 0.75
    if s == "さて":
        return None, 0.5
    return None, 0.0

programs.sol:
"""A negation-sensitive lexical signal, especially denial of 'being'.

Finite copula + 'not' and 'isn't'-type contractions get large negative
values. Other auxiliaries, selected multilingual negations, and inequality
signs get smaller values. English case and token boundaries adjust the
strength. Two preceding tokens recognize single intervening
adverbs and existential 'there'. A few small copula-complement responses are
included; other tokens predict zero. Reset context at document boundaries.
Split Unicode negation characters are recognized when their bytes complete.
The constants approximate training averages, not all lexical variation.
"""
READS = ()

# Strength of a separate 'not' after each English auxiliary.
AUXILIARIES = {
    'is': -3.9, 'are': -3.7, 'am': -3.7, 'was': -3.7, 'were': -3.4,
    'be': -1.5, 'been': -1.5, 'being': -1.5,
    "'s": -3.15, "'re": -3.4, "'m": -3.8,
    'do': -1.0, 'does': -1.0, 'did': -0.9,
    'will': -1.2, 'would': -1.2, 'may': -1.25, 'might': -1.1,
    'shall': -1.05, 'should': -1.55, 'must': -0.6,
    'can': -0.3, 'could': -0.3, 'need': -0.6,
    'have': -0.8, 'has': -0.85, 'had': -0.65,
}
COPULAS = {'is', 'are', 'am', 'was', 'were', "'s", "'re", "'m"}

# Stems before the final 't token in negative contractions.
CONTRACTIONS = {
    'isn': -3.7, 'aren': -3.4, 'wasn': -3.55, 'weren': -3.0,
    'ain': -2.1, 'don': -1.23, 'doesn': -1.1, 'didn': -1.1,
    'won': -1.0, 'wouldn': -1.2, 'shouldn': -1.7,
    'can': -0.55, 'couldn': -0.48,
    'haven': -1.05, 'hasn': -1.15, 'hadn': -0.9,
}

# Explicit negation words and particles in several languages.
NEGATIONS = {
    'не': -0.78, 'nicht': -1.3, 'niet': -0.82, 'ikke': -0.93,
    'non': -1.08, 'không': -0.6, 'tidak': -0.62,
    'ليس': -2.0, 'ليست': -2.0, '아니': -1.9, 'ไม': -0.92,
    'ない': -0.25, 'ではない': -1.2, 'ではなく': -0.85,
    '不': -0.8, '不要': -0.85, '不会': -0.6, '不能': -0.35,
    '不了': -0.75, '也不': -1.1, '不同': -0.5,
    '并不': -2.4, '並不': -2.2, '并非': -5.0, '非': -3.0,
    '而非': -1.9, '而不是': -1.4, '是不是': -3.0,
    '不是很': -3.15, '不是一个': -3.2,
    '不止': -2.2, '不只是': -2.4, '不仅仅': -2.1, '不一定': -2.2,
}
ADVERBS = {
    'really', 'just', 'still', 'also', 'simply', 'actually', 'probably',
    'definitely', 'certainly', 'clearly', 'obviously', 'usually',
    'generally', 'often', 'currently', 'necessarily', 'entirely',
    'quite', 'even', 'yet', 'always', 'surely', 'normally',
}


def normalize(token):
    return token.strip().lower().replace('’', "'").strip('_')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    prev_token, before_token = ('', '') if fresh else carry[1:]
    previous, before = normalize(prev_token), normalize(before_token)
    token = prefix.token_strings[-1]
    raw = token.strip().replace('’', "'")
    word = normalize(token)
    value = 0.0
    if word == 'not':
        value = AUXILIARIES.get(previous, -0.3)
        if previous in ADVERBS:
            value = 0.55 * AUXILIARIES.get(before, -1.3)
            if before not in AUXILIARIES and previous in {'still', 'probably'}:
                value = -1.6
        elif previous in COPULAS:
            if before == 'there':
                value += 1.5
            elif before in {'it', 'this'}:
                value -= 0.3
            elif before == 'which':
                value += 0.35
        elif previous in {'and', 'but', 'or', 'if', 'why', ',', ';', ':'}:
            value = 0.0
        if raw == 'NOT':
            value *= 0.7
        elif raw == 'Not' and previous not in AUXILIARIES:
            value *= 0.15
        elif raw.startswith('_'):
            value *= 0.9
        elif not token[:1].isspace():
            value *= 0.4
        if fresh:
            value = -1.0
    elif word in {"'t", "n't"}:
        value = CONTRACTIONS.get(previous, -0.7)
        if previous in {'isn', 'aren', 'wasn', 'weren'}:
            if before == 'there':
                value += 1.4
            if prev_token.strip()[:1].isupper():
                value += 0.6
    elif '\ufffd' in token:
        # A token may finish a character that could not decode on its own.
        character = prefix.text_prefixes[-1][-1:]
        value = NEGATIONS.get(character, 0.0)
        if character == '非':
            value = -3.4
    elif '!=' in word:
        value = -1.65 if token[:1].isspace() else -1.2
    elif word == '≠':
        value = -0.65
    elif word in NEGATIONS:
        value = NEGATIONS[word]
    elif '不是' in word:
        value = -6.3 if previous in {'并', '並'} else -4.5
    elif word.strip('/-.') == 'non':
        value = -1.08
    elif word == 'it' and previous in COPULAS:
        value = -1.3 if prev_token.strip()[:1].isupper() else -1.0
    elif word == 'be' and previous in {'not', "'t", "n't"}:
        value = -0.4
    elif word in {'also', 'no', 'only'}:
        value = -0.3 if previous in COPULAS else 0.12
    elif word in {'as', 'of'} and previous in COPULAS:
        value = 0.45 if word == 'as' else 0.3
    return (doc, token, prev_token), value

programs.haiku:
"""Negation detector for layers.0.mlp.down_proj:1379.

The component goes negative on negation words, and by how much depends on the word before:
  - "is not", "are not", "was not", "isn't", "'s not" (a form of "be" + negation): about -3.7
  - "do not", "can't", "will not", "should not" (auxiliary + negation): about -1.1
  - "and not", ", not", "but not", sentence-initial "Not": about 0
Other negators: Chinese 不是 / 非 / 不, German nicht, Russian не, Arabic ليس, Korean 아니,
and the "non-" prefix and "!=" operator, each at a fixed rough strength.
Every other token is predicted as 0.
"""

READS = ()

# Forms of "be" (and their contractions) that a negation can follow.
BE = {"is", "are", "was", "were", "am", "'s", "’s", "'m", "’m", "'re", "’re",
      "isn", "aren", "wasn", "weren"}
# Auxiliaries and modals that a negation can follow.
AUX = {"do", "does", "did", "don", "doesn", "didn", "can", "will", "won", "would",
       "wouldn", "should", "shouldn", "may", "might", "must", "could", "couldn",
       "has", "have", "had", "hasn", "haven", "hadn", "need"}
# English negation words.
NOT = {"not", "NOT", "n't", "'t", "’t"}
# Fixed strengths for the other negators.
FIXED = {"non": -1.2, "!=": -1.6, "nicht": -1.3, "не": -0.6, "ليس": -2.0, "아니": -2.0}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if "非" in tok or "不是" in tok:
        return carry, -3.5
    if "不" in tok:
        return carry, -1.5 if "并" in tok else -0.8
    if tok in FIXED:
        return carry, FIXED[tok]
    if tok in NOT:
        if prev in BE:
            return carry, -3.7
        if prev in AUX:
            return carry, -1.1
    return carry, 0.0

