"""Approximate a turn-ending newline pulse and Chinese name continuations."""

READS = ()
COMMON_HAN_SURNAMES = frozenset(
    "王李张刘陈杨黄赵周吴徐孙朱马胡郭林何高罗郑梁谢宋唐许韩冯邓曹彭"
    "曾萧田董袁潘于蒋蔡余杜叶程苏魏吕丁任沈姚"
)


def is_han(text):
    return any("\u3400" <= char <= "\u9fff" for char in text)


def step(carry, prefix, upstream):
    """Use a turn-ending newline and common-surname sequence as sparse cues."""
    tokens = prefix.token_strings
    value = 0.0
    if len(tokens) > 1:
        current, previous = tokens[-1], tokens[-2]
        documents = prefix.document_ids
        same_document = documents[-1] == documents[-2]
        if same_document:
            if current == "\n" and previous == "<|im_end|>":
                value = -0.48
            elif len(previous) == 1 and previous in COMMON_HAN_SURNAMES and is_han(current):
                value = 0.06
    return None, value

