"""A sparse English explanation/answer phrase recognizer.

The largest responses are to 'you explain', 'please explain', 'your answer'
and 'correct answer'. Result/proof and procedure/rule nouns have smaller,
determiner-sensitive responses. A few explanation and follow-up continuations
also respond. These rules approximate salient lexical peaks, not all activity. Lowercase running-text words are distinguished
from capitalized headings. Other activity is approximated by zero.
"""
READS = ()
POSSESSIVES = {'my', 'your', 'our', 'his', 'her', 'their'}
MODALS = {'can', 'could', 'will', 'would', 'may'}
NOUNS = {'result', 'results', 'proof', 'method', 'rule', 'rules',
         'law', 'laws', 'code'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prior, previous = '', ''
    if carry is not None and carry[0] == doc:
        prior, previous = carry[1:]
    token = prefix.token_strings[-1].strip()
    word = token.lower()
    value = 0.0

    if token == 'explain':
        value = 0.06
        if previous == 'you':
            value = 0.70
        elif previous == 'please':
