    "answer", "explain", "demonstrate", "method", "result", "results",
    "purpose", "show",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = "".join(prefix.token_strings[max(0, prefix.position - 4):
                                        prefix.position]).lower()
    if word == "void":
        return None, -0.17
    if word == "explain":
        if "please" in before or "can you" in before or "could you" in before:
            return None, 0.65
        return None, 0.05
