# Common location adverbs/nouns: Chinese, Japanese, Russian, Romance, Korean, Arabic.
LOCATION_ADVERBS = {
    '哪里': 1.3, '这里': 1.0, '那里': 0.85,
    '哪儿': 0.5, '这儿': 0.8, '那儿': 0.75,
    '這裡': 1.25, '哪裡': 1.3, '那裡': 0.85,
    'どこ': 1.6, 'ここ': 1.5, 'そこ': 1.13, 'ところ': 0.91,
    '地方': 0.95, '的地方': 1.81,
    'наход': 1.65, 'находится': 0.76, 'где': 0.8, 'donde': 0.65, 'dónde': 0.65, 'où': 0.55,
    '여기': 0.8, '어디': 0.78, 'حيث': 0.61,
