    raw = prefix.token_strings[-1]
    word = raw.strip()
    lower = word.lower().lstrip('._(\t')
    value = 0.0
    if '\ufffd' in raw:
        if (prefix.position == 0
                or prefix.document_ids[-1] != prefix.document_ids[-2]):
            return None, 0.0
        # A byte-split character is identifiable only once its final byte arrives.
        completed = prefix.text_prefixes[-1][-1:]
        value = {'处': 8.5, '處': 6.7, '処': 5.62, '所': 0.83}.get(
            completed, 0.0)
        return None, value
    if lower == 'where':
        if word.isupper():
            value = 1.25
        elif word[:1].isupper():
            value = 1.18
        else:
