    elif lower in {'somewhere', 'everywhere', 'elsewhere'}:
        value = 1.1
    elif lower == 'anywhere':
        value = 0.98
    elif lower == 'nowhere':
        value = 0.8
    elif lower == 'wherever':
        value = 1.28
    elif lower in {'wherein', 'herein'}:
        value = 0.41
    elif lower == 'treatment':
        value = 0.38 if word[:1].isupper() else 0.23
    elif lower == 'processor':
        value = 0.30 if word == 'Processor' else 0.50
    elif lower == 'handler':
        value = 0.38 if word == 'Handler' else 0.25
    elif lower in {'processing', 'handling'}:
        value = 0.17
    elif word in LOCATION_ADVERBS:
        value = LOCATION_ADVERBS[word]
    elif word == '처리':
        value = 1.36 if raw.startswith(' ') else 1.05
    elif word == '処':
        value = 5.62
    elif word == '처':  # Korean place / handling syllable
        value = 3.45 if raw.startswith(' ') else 2.25
    else:
        chinese = word.replace('處', '处')
        if chinese == '处':
            value = 7.05 if word == '处' else 6.68
        elif chinese == '处处':
            value = 6.05
        elif chinese == '处于':
            value = 2.64
        elif chinese == '处在':
            value = 3.44
        elif chinese == '处分':
            value = 2.85
        elif chinese.endswith('处'):
            modifier = chinese[:-1]
            if modifier == '一':  # one place
                value = 5.7
            elif modifier == '到':  # everywhere
                value = 4.8
            elif modifier == '四':  # all around
                value = 5.5
            elif modifier in {'之', '出'}:  # place / source
                value = 3.9
            elif modifier in {'何', '此', '身'}:  # where / here / situated in
                value = 3.5
            elif modifier == '相':  # getting along
                value = 1.8
            elif len(modifier) > 1 or modifier == '查':
                value = 1.1
            else:
                value = 2.4
        elif chinese.startswith('处'):
            value = 3.3 if chinese.startswith('处处') else 1.4
        elif word == '所':  # place, also a Chinese grammatical particle
            value = 0.72
