"""Location words: 'where' and its kin in several languages, and the Chinese place character 处."""
READS = ()
WHERE_WORDS = {"where", "wherever", "somewhere", "everywhere", "anywhere", "elsewhere", "nowhere"}
PLACE_WORDS = {"这里", "那里", "哪里", "地方", "这儿", "哪儿", "那儿", "此处", "ここ", "そこ", "どこ",
               "где", "здесь", "où", "donde", "находится", "這裡", "哪裡"}
PLACE_CHARS = set("处處")
PLACE_CHAR_OTHER = {"处理", "處理", "处置", "处分", "处方", "处境", "处罚", "处长", "相处"}

