programs.sol:
"""Number-following arithmetic and count expressions.

A slash immediately after a digit has the largest negative response. Other
arithmetic separators, ordinal endings, and counted nouns also turn negative
after digits. Plural time units respond positively without an explicit number,
especially after words referring to earlier/later periods; written-out numbers
have an intermediate response. Slash strength is adjusted for the length and
last digit of the number, decimal/negative notation, and document position.
The state resets at document boundaries. Coefficients are training estimates;
small lexical responses outside these classes are deliberately omitted.
"""
READS = ()
NUMBER_WORDS = set('''one two three four five six seven eight nine ten eleven
    twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen twenty
    thirty forty fifty sixty seventy eighty ninety hundred thousand million
    billion'''.split())
EARLY_LATE = set('early earliest first last past previous later old'.split())
RECENT_FUTURE = set('recent coming following subsequent former final'.split())
QUANTIFIERS = set('many few several multiple couple numerous'.split())
FUNCTION_WORDS = set('the these those this of for in on during after'.split())
# Columns: after digit, after written number, otherwise (before context adjustment).
TIME_UNITS = {
    'years': (-0.81, 0.33, 0.85),
    'days': (-0.96, 0.45, 1.05),
    'months': (-0.21, 0.71, 1.15),
    'weeks': (-0.36, 0.77, 1.05),
    'hours': (-0.83, 0.14, 0.50),
    'minutes': (-1.10, -0.11, 0.20),
    'seconds': (-0.87, -0.10, -0.13),
    'decades': (-0.70, 0.26, 0.65),
    'centuries': (-0.75, 0.13, 0.33),
}
NOT_PLURAL = set('as is was has his this thus yes its us'.split())
CLOSING_BRACKETS = set(')]}')
COUNTABLE = set('''items words points games pages lines rows parts characters
    books feet degrees tests ways steps goals pounds stones dollars units cells
    patients'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position, run, number_prefix = '', 0, 0, ''
    else:
        _, previous, position, run, number_prefix = carry
        position += 1
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    before = previous.strip().lower()
    digit = bool(before) and before[-1] in '0123456789'
    written = before.lstrip('-') in NUMBER_WORDS
    value = -0.003

    if word in TIME_UNITS:
        numeric, spelled, base = TIME_UNITS[word]
        if digit:
            value = numeric
        elif written:
            value = spelled
        else:
            extra = (2.40 if before in EARLY_LATE else
                     1.40 if before in RECENT_FUTURE else
                     0.50 if before in QUANTIFIERS else
                     0.88 if before in FUNCTION_WORDS else 0.42)
            value = base + extra
    elif word in {'/', '／'}:
        spaced = token.startswith(' ')
        if token.endswith('\n'):
            value = -1.0 if digit else -0.05
        elif digit:
            if spaced or word == '／':
                value = -2.12 if spaced else -1.15
            else:
                # Longer numbers and early-document fractions are stronger.
                last_digit = int(before[-1])
                value = (-2.60 - 0.04 * last_digit - 0.40 * (run > 1)
                         - 2.63 / (position + 1) ** 0.5)
                if number_prefix == '.':
                    value += 0.38
                elif number_prefix.endswith('-'):
                    value += 0.23
        elif before in {'pi', '(pi', 'π', '²', '³'}:
            value = -1.15 if spaced else -1.65
        elif (len(before) == 1 and before.isalpha() or
              before[-1:] in CLOSING_BRACKETS):
            value = -0.85 if spaced else -1.20
        else:
            value = -0.8 if word == '／' else -0.25
    elif '/' in word:
        if word.startswith((')', ']', '}')):
            value = -1.5 if digit else -0.9
        elif word.startswith('/'):
            if word == '/(':
                value = -1.7 if digit else -0.7
            elif len(word) == 2:
                value = -1.3 if digit else -0.10
            else:
                value = -0.6 if digit else 0.0
    elif word == '}{':
        value = -1.64 if digit else -0.48
    elif word in {'*', '^', '^{' }:
        value = (-0.75 if token.startswith(' ') else -1.0) if digit else -0.03
    elif word in {'*(', '*(-', ')^', '×', '²', '³', '\\'}:
        value = -0.60 if digit else -0.04
    elif word in {'+', 'x', 'y', 'k'} and digit:
        value = -0.1 if token.startswith(' ') else -0.3
    elif word in {'st', 'nd', 'rd', 'th', 'ª', 'º'}:
        value = (-0.81 if word == 'th' else -0.5) if digit else (
            -0.4 if written else -0.03)
    elif word == 'times':
        value = (-2.2 if digit else -1.15 if written else
                 0.15 if before in QUANTIFIERS else 0.6)
    elif word == 'views':
        value = -3.1 if digit else -1.8 if written else -0.1
    elif word in {'people', 'students', 'men'}:
        value = -1.5 if digit else -0.65 if written else -0.02
    elif word in {'of', 'by', 'and', 'to', 'divided'} and digit:
        value = {'of': -0.8, 'by': -0.19, 'and': -0.13,
                 'to': 0.09, 'divided': -1.2}[word]
    elif word in {'more', 'terms', 'observations'}:
        value = -1.9 if digit else -0.75 if written else (
            0.03 if word == 'more' else -0.12)
    elif word in COUNTABLE:
        value = -0.95 if digit else -0.30 if written else 0.13
    elif word in {'hundred', 'thousand', 'million', 'billion'}:
        if word in {'million', 'billion'}:
            value = -0.23 if digit else 0.0
        else:
            value = -1.2 if digit else -0.6 if written else -0.1
    elif word in {'hundreds', 'thousands', 'millions', 'billions'}:
        value = 0.8
    elif word in {'year', 'day', 'week', 'month', 'hour', 'minute', 'second'}:
        value = (-0.2 if word == 'year' else -0.7) if digit else 0.15
    elif word in {'日', 'рублей', 'году', 'года'}:
        value = (-0.27 if word == '日' else -0.7) if digit else 0.0
    elif (token.startswith(' ') and word.isalpha() and len(word) > 2 and
          word.endswith('s') and word not in NOT_PLURAL):
        value = -0.55 if digit else -0.25 if written else 0.01
    if word and all(c in '0123456789' for c in word):
        if not digit:
            run, number_prefix = 0, before
        run += len(word)
    else:
        run, number_prefix = 0, ''
    return (doc, token, position, run, number_prefix), float(value)

programs.haiku:
"""Division-like symbols and unit words attached to a numeral (negative); time-span nouns in
ordinary prose (positive)."""
READS = ()
SLASHES = {"/", "/(", " /", ")/", "}/", "}{", "/m", "/s", "/N", "/x", "/n", "/p", "/d", "/c", "/r"}
MATH_OPS = {"*", "*(", "^", "^{", "×", ")^", "x", "+", "\\"}
COUNT_UNITS = {" years", " days", " weeks", " months", " hours", " minutes", " seconds",
               " times", " views", " people", " pages", " words", " feet", " pounds", " stones",
               " students", " votes", " games", " shots", "th"}
TIME_SPANS = {" years", " days", " weeks", " months", " hours", " decades", " thousands", " Days"}
def _ends_in_digit(s):
    s = s.strip()
    return len(s) > 0 and s[-1].isdigit()
def _is_symbol_or_letter(s):
    s = s.strip()
    return len(s) == 1 and not s.isdigit()
def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    after_num = _ends_in_digit(prev)
    if after_num:
        if cur == "/":
            return None, -3.0
        if cur in SLASHES:
            return None, -1.8
        if cur in MATH_OPS:
            return None, -1.0
        if cur in COUNT_UNITS:
            return None, -1.0
        return None, 0.0
    if cur == "/":
        return None, -1.1 if _is_symbol_or_letter(prev) else -0.1
    if cur in TIME_SPANS:
        return None, 1.2
    return None, 0.0

