"""Approximate numeric separators, ordinal endings, and quantity labels."""
import re

READS = ()

BEFORE_NUMBER = re.compile(r"\d\s*$")
NUMBER = re.compile(
    r"(?:\d+(?:[.,]\d+)*|zero|one|two|three|four|five|six|seven|eight|nine|"
    r"ten|eleven|twelve|dozen|hundred|thousand|million)\s*$", re.I
)
ORDINAL_ENDINGS = {"st", "nd", "rd", "th", "ª", "º"}
COUNT_WORDS = {
    "year", "years", "month", "months", "day", "days",
    "hour", "hours", "minute", "minutes", "second", "seconds",
    "people", "person", "worker", "workers", "point", "points",
    "game", "games", "word", "words", "rating", "ratings",
    "mile", "miles", "kilometer", "kilometers", "percent", "times",
}

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        context = ""
    else:
        context = carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if word == "/":
        value = -2.8 if BEFORE_NUMBER.search(context) else -0.3
    elif word in ORDINAL_ENDINGS and BEFORE_NUMBER.search(context):
        value = -0.65
    elif word in COUNT_WORDS and NUMBER.search(context):
        value = -0.45
    elif word == "thousands" and re.search(r"tens\s+of\s*$", context, re.I):
        value = 0.7
    else:
        value = 0.0
    return (doc, (context + token)[-100:]), value

