"""A surface detector for hesitation and reconsideration.

The strongest response is negative on 'Hmm', especially without a leading
space. Some thinking interjections, caution/complication words, and forms of
'contradict' have smaller negative responses. Recent reconsideration cues or
math notation strengthen the caution and complication responses. The cue
lasts 64 tokens, resets at document boundaries, and otherwise predicts zero.
"""
READS = ()
CAUTION = {'careful', 'carefully', 'reasonable', 'reasonably'}
COMPLICATION = {'complicated', 'messy'}
CUES = {'Hmm', 'Wait', 'Alternatively', '<think>', '=', '^', '²'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous = 0, ''
    else:
        recent, previous = max(0, carry[1] - 1), carry[2]
    if word in CUES:
        recent = 64
    value = 0.0
    if word == 'Hmm':
        value = -0.93 if token.startswith(' ') else -1.10
    elif word == 'hmm':
        value = -0.47
    elif word in {'Ah', 'Okay', 'Well'}:
        value = -0.055 if token.startswith(' ') else -0.15
    elif word == 'Oh':
        value = -0.065
    elif word in CAUTION:
        value = -0.36 if recent else -0.17
    elif word in COMPLICATION:
        value = -0.63 if recent else -0.27
    elif word == 'might':
        value = -0.21 if recent else -0.09
    elif word == 'perhaps':
        value = -0.11 if recent else 0.0
    elif word.startswith('contrad'):
        value = -0.30
    elif word == 'icts' and previous.endswith('contrad'):
        value = -0.47
    elif word == '<think>':
        value = -0.165
    return (doc, recent, word), float(value)

