"""Layer 0, MLP down-projection, component 1386: a hesitation / self-doubt detector.

Its activation is negative on words that show a reasoning model pausing or doubting
its own work, and it is near zero elsewhere:
  - "Hmm" / "hmm" (also Chinese 嗯): strongest, about -1 (or -0.3 for the Chinese).
  - words of difficulty or error in working: "complicated", "contradiction",
    "careful", "typo", "messy", "tedious", ...: about -0.3.
  - mild hedges such as "might", "either", "something", "various": about -0.1.
Everything else is predicted as 0. The per-token scale is set by hand from the
component's mean activation on training text, not fitted.
"""

READS = ()

HMM = {"Hmm", "hmm"}
CHINESE_HMM = {"嗯"}
DIFFICULTY = {
    "complicated", "contradiction", "contradict", "contrad", "careful", "typo",
    "messy", "tedious", "hairy", "clever", "hopeless", "confusing", "smarter",
}
HEDGES = {
    "might", "either", "else", "something", "various", "often", "actually",
    "perhaps", "somewhat",
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lower()
    if token in HMM:
        value = -1.0
    elif token in CHINESE_HMM:
        value = -0.3
    elif word in DIFFICULTY:
        value = -0.3
    elif word in HEDGES:
        value = -0.1
    else:
        value = 0.0
    return carry, value

