"""Recognize hesitation interjections, with a stronger pulse for “Hmm”."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    previous, previous_document = carry or ("", None)
    document = prefix.document_ids[-1]
    if document != previous_document:
        previous = ""

    lower = word.casefold()
    if lower == "hmm":
        # The capitalized form is the common start of a reflective sentence.
        value = -1.1 if word == "Hmm" else -0.5
        if token[:1].isspace() and word == "Hmm":
            value = -0.92
    elif lower in {"hm", "hmmm"}:
        value = -0.8
    elif lower == "mmm" and previous.strip().casefold().endswith("h"):
        value = -0.17
    else:
        value = -0.00184
    return (token, document), value

"""Recognize alternative/contrast language and the assistant role label."""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].lower().strip()
    baseline = 0.004

    if "instead" in word:
        return None, baseline + 6.8

    if any(part in word for part in (
        "alternat", "equival", "rather", "substitut", "replac",
        "another", "elsewhere", "proxy", "alias", "avoid",
    )):
        return None, baseline + 1.4

    contrast_words = (
        "despite", "nonetheless", "nevertheless", "regardless",
        "although", "whereas", "consequently", "maybe",
    )
    if word == "than" or word == "assistant" or any(
        part in word for part in contrast_words
    ):
        return None, baseline + 0.65

    return None, baseline

programs.haiku:
"""Layer-0 MLP feature: the start of a Chinese word or phrase.

The component fires on Chinese (Han) words that begin a new phrase: a two-character
word such as 文字, 今年, 中国, 非常, 考生, 国产 or 家属 fires strongly, most of all
right after a line break or a list/clause mark (、 ， 。). The same word continuing a
run of Chinese text (for example right after another Chinese word) fires about half
as much. Three-character words fire moderately at a phrase start and weakly inside a
run. A single Chinese character fires only weakly, and only at a phrase start. Two-
character words ending in a grammatical particle (的, の, 了, 是, 在, 和 ...) do not
fire inside a run. Hangul, kana, English, code, punctuation and spaces are about
zero (chat markup such as </think> is not modelled).

Only the current token and the one before it are read, and the previous token only
counts within the same document.
"""

READS = ()

# Grammatical particles and function-word endings: a two-character word ending in one
# of these inside a Chinese run is usually a grammar fragment (X的, X了, X是), not a
# content word.
PARTICLE_ENDINGS = set("的のてたンすら了は是和在要がをにとでね")


def is_han(ch):
    code = ord(ch)
    return 0x4E00 <= code <= 0x9FFF or 0x3400 <= code <= 0x4DBF  # CJK ideographs


def is_han_text(text):
    return bool(text) and all(is_han(ch) for ch in text)


def phrase_start_weight(prev):
    """How strongly a new Chinese word fires, given the token just before it."""
    if prev == "\n":
        return 1.6
    if prev == "、":
