programs.sol:
"""Predict the signed response to adjacent decimal digits.

The main response distinguishes the parity of the preceding digit. It rises
with the current digit after 2/4/6/8, falls after 3/5/7, and has a broad
middle-digit peak after 9. A preceding zero or one suppresses this response.
After a decimal point or comma, smaller curves depend on the digit before
the separator, if any. Predictions at fullwidth digits are attenuated.
The short curves are fitted approximations, not a claim about arithmetic use.
"""
READS = ()


def digit(text):
    if len(text) == 1 and ('0' <= text <= '9' or '０' <= text <= '９'):
        return int(text)
    return -1


def adjacent(before, current):
    d = current
    if before < 2:
        return 0.0
    if before % 2 == 0:
        if before == 2:
            return -1.65 + 0.83*d - 0.020*d*d
        if before == 6:
            return -1.86 + 0.73*d + 0.007*d*d
        return -1.49 + 0.65*d - 0.004*d*d
    if before == 9:
        return 0.81 + 0.22*d - 0.020*d*d
    if before == 7:
        return 1.62 - 0.064*d - 0.008*d*d
    return 1.56 - 0.10*d - 0.010*d*d


def decimal(before, current):
    d = current
    if before in (2, 4, 6, 8):
        return -1.11 + 0.43*d
    if before in (3, 5, 7):
        return 0.17 + 0.11*d - 0.002*d*d
    if before == 9:
        return -0.21 + 0.22*d - 0.006*d*d
    if before == 1:
        return -0.10 + 0.11*d + 0.001*d*d
    return -0.44 + 0.17*d + 0.003*d*d


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous = '', ''
    else:
        _, previous, before_previous = carry
    current = digit(token)
    value = 0.0
    if current >= 0:
        before = digit(previous)
        if before >= 0:
            value = adjacent(before, current)
        elif previous in ('.', ','):
            value = decimal(digit(before_previous), current)
            if previous == ',':
                value = 0.5*value - 0.08
        if '０' <= token <= '９':
            value *= 0.8
    return (doc, token, previous), float(value)

