"""Digit-pair detector for layers.0.mlp.down_proj:1393.

The component is silent almost everywhere. It fires on a digit that comes right after
another digit inside a number (the "2" of 12, the "9" of 390, the "8" of 2008). Its size
depends on the pair of digits:

- previous digit 0 or 1: silent (0);
- previous digit even (2, 4, 6, 8): negative for small digits, rising steadily with the
  size of the current digit (about -1.6 after a 2 for "0", about +4 for "9");
- previous digit 3, 5 or 7: positive, strongest for a small current digit (about +1.6
  for "0", fading to about 0 at "9");
- previous digit 9: a mild positive value (about +1.1) for any current digit.

A digit separated from the previous digit by a single "." (as in 4.9 or 2.7) gets about half
the same value. Everything else, including the first digit of a number, is 0.

Put simply, it reads the decimal digits of a number pairwise and writes a signal whose sign
and size depend on the parity and size of the two digits.
"""

READS = ()

DIGITS = frozenset("0123456789")


def pair_value(prev, cur):
    """Activation for digit `cur` directly after digit `prev`."""
    p, c = int(prev), int(cur)
    if p < 2:
        return 0.0
    if p % 2 == 0:
        return -1.6 + 0.67 * c
    if p == 9:
        return 1.1
    return 1.63 - 0.16 * c


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    n = len(tokens)
    if n < 2 or docs[-1] != docs[-2]:
        return carry, 0.0
    cur = tokens[-1]
    if cur not in DIGITS:
        return carry, 0.0
    if tokens[-2] in DIGITS:
        return carry, pair_value(tokens[-2], cur)
    if n >= 3 and tokens[-2] == "." and docs[-3] == docs[-1] and tokens[-3] in DIGITS:
        return carry, 0.5 * pair_value(tokens[-3], cur)
    return carry, 0.0

