"""layers.0.mlp.down_proj:1398 -- a negative "MS / ms abbreviation" detector.

The component is almost silent everywhere. It goes strongly negative on the token
for the abbreviation MS / ms (milliseconds, as in "50 ms" or "(50ms)", and MS as in
multiple sclerosis or the all-caps acronym "LMSYS"), and more weakly on other short
acronyms and fragments built from the letters m and s (CMS, SMS, Ms., msg, message).
It is a token-identity feature: it reads the token just written and ignores context,
apart from the milliseconds case, where a digit just before "ms" makes it stronger.

Prediction: the activation on the current token (never later tokens).
"""

READS = ()


def activation_of_token(token, previous):
    """Activation for one token, given the token text and the token before it."""
    text = token.strip()
    low = text.lower()
    if text == "MS":
        return -4.9
    if low == "ms":
        # "50 ms" / "(50ms)": a unit after a number is the strongest case
        if previous.strip().replace(".", "").isdigit():
            return -4.0
        return -3.3
    if text == "Ms":
        return -1.5  # title "Ms." before a surname
    if low in ("millisecond", "milliseconds"):
        return -2.0
    if text.isupper() and "MS" in text and len(text) <= 5:
        return -1.5  # acronyms such as CMS, SMS, RMS, MSC, MSG
    if low in ("cms", "sms", "rms"):
        return -2.8
    if low in ("ams", "ims", "ems", "ums", "oms"):
        return -0.6
    if low in ("msg", "_msg") or "message" in low:
        return -0.9
    return 0.0


def step(carry, prefix, upstream):
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    return None, float(activation_of_token(prefix.token_strings[-1], previous))

