"""Spanish-only layer-0 feature (silent in English text).

In Spanish text the component goes negative on the words that sit directly before a
verb, and positive on the words that sit directly before a noun:
  * clitic pronouns se / nos / te and the negation 'no' go strongly negative, most
    strongly right after a subordinator or subject (que se, que no, y no, aunque no);
  * auxiliaries ha / han / hemos go negative;
  * possessives su / sus / tu / mi go positive, and the article 'el' moderately so.
Its size is scaled by how Spanish the recent text is (decayed count of Spanish
versus English function words in this document)."""
READS = ()
SPANISH = set("de la el que y en los las se no un una es por para con del al lo su sus mas como pero le nos ha han o este esta ya fue son".split())
ENGLISH = set("the of and to is in that it for with on as are was be this by at from an or which have has".split())
BEFORE_VERB = {" que", ",", " y", " aunque", " porque", " si", " donde", " cuando", " para", " yo", " ya", " nunca", " tampoco"}
STRONG_CLITIC = {" se", " Se", " nos", " te", " Te"}
NEGATION = {" no", " No"}
WEAK_CLITIC = {" me", " Me", " le", " les", " lo"}
AUX = {" ha", " han", " hemos"}
POSSESSIVE = {" su", " Su", " sus", " tu", " mi", " mis"}
ARTICLE = {" el", " El"}
DECAY = 0.97

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    new_doc = len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    es, en = (0.0, 0.0) if (carry is None or new_doc) else carry
    es *= DECAY
    en *= DECAY
    word = tok.strip().lower()
    if word in SPANISH:
        es += 1
    if word in ENGLISH:
        en += 1
    spanish = es / (es + en + 1.0)
    after_verb_cue = prev in BEFORE_VERB
    if tok in STRONG_CLITIC:
        base = -3.3 if after_verb_cue else -1.5
    elif tok in NEGATION:
        base = -2.3 if after_verb_cue else -0.7
    elif tok in WEAK_CLITIC:
        base = -0.3
    elif tok in AUX:
        base = -1.35
    elif tok in POSSESSIVE:
        base = 1.9
    elif tok in ARTICLE:
