"""Estimate possessive versus reflexive/negative Spanish function words."""
READS = ()

SPANISH_CUES = {
    "el", "la", "los", "las", "un", "una", "unos", "unas",
    "de", "del", "que", "y", "en", "es", "con", "por", "para",
    "como", "pero", "porque", "al", "muy", "más", "sí",
}
ACCENTS = "áéíóúñ¿¡"


def starts_word(prefix, index):
    token = prefix.token_strings[index]
    if token[:1].isspace() or index == 0:
        return True
    previous = prefix.token_strings[index - 1]
    return not previous or previous[-1].isspace() or not previous[-1].isalnum()


def step(carry, prefix, upstream):
    i = prefix.position
    word = prefix.token_strings[i].strip().casefold()
    if not starts_word(prefix, i):
        return None, -0.0025

    clues = 0
    for j in range(max(0, i - 12), i):
        token = prefix.token_strings[j]
        if not starts_word(prefix, j):
            continue
        if token.strip().casefold() in SPANISH_CUES:
            clues += 1
        elif any(char in token for char in ACCENTS):
            clues += 1

    if clues >= 2 and word == "tu":
        return None, 1.5
    if clues >= 2 and word in {"su", "sus"}:
        return None, 0.8
    if clues >= 2 and word == "no":
        return None, -1.0
    if clues >= 2 and word in {"se", "nos"}:
        return None, -2.0
    return None, -0.0025

"""Use a tiny case-sensitive estimate for alphabetic word fragments."""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    piece = token.strip()
    if not piece or token[:1].isspace() or not piece.isalpha():
        return None, 0.0
    if piece.islower():
        return None, -0.001
    if piece.isupper():
        return None, 0.001
    return None, 0.0

