    value = -0.002
    plural = lower.endswith('s') and lower[:-1] in NATIONALITIES
    nationality = lower[:-1] if plural else lower
    if nationality in NATIONALITIES:
        value = 0.44
        if nationality in STRONG_NATIONALITIES:
            value = 0.63
        elif nationality in WEAKER_NATIONALITIES:
            value = 0.31 if nationality != 'american' else 0.15
        elif nationality == 'chinese':
            value = 0.85
        if nationality in {'polish', 'thai'} and word.islower():
            value = 0.01
        if plural:
            value *= 0.85
    elif lower in COUNTRIES:
        value = 0.24
        if lower in STRONG_COUNTRY_NAMES:
            value = 0.38
        elif lower == 'china':
            value = 0.63
        if not word[:1].isupper():
            value *= 0.5
    elif lower in {'european', 'african', 'asian', 'latin'}:
        value = 0.32 if lower == 'asian' else 0.19
        if lower == 'african':
            value = 0.08
    elif lower in {'national', 'international'}:
        value = 0.31 if lower == 'national' else 0.23
        if word.islower():
            value = 0.18 if lower == 'national' else 0.14
    elif lower in {'soviet', 'ussr', 'marxist', 'lenin', 'stalin'}:
        value = 0.76
    elif lower in {
        'communist', 'socialist', 'islamic', 'muslim', 'hindu', 'buddhist', 'nazi',
    }:
        value = 0.48
    elif lower in {'roman', 'ottoman', 'byzantine', 'victorian'}:
        value = 0.32
    elif lower in {'london', 'moscow', 'beijing', 'shanghai', 'budapest', 'athens'}:
        value = 0.27
    elif lower in {'islam', 'catholic', 'republic'} or word == 'UK':
        value = 0.20

    # Chinese country and state vocabulary, including merged tokens.
    if any(c in word for c in '国國'):
        value = 0.53
        if word in {'国', '國'} or any(s in word for s in (
            '中国', '中國', '我国', '我國', '英国', '英國',
            '德国', '德國', '俄国', '俄國', '韩国', '韓國',
        )):
            value = 0.90
        if '美国' in word or '美國' in word:
            value = 0.46
    elif '日本' in word:
        value = 0.64
    elif any(s in word for s in ('社会主义', '社會主義', '马克思', '克思主义')):
        value = 0.90
    elif any(c in word for c in '党黨'):
        value = 0.45
        if '党的' in word or '黨的' in word:
            value = 1.18
    elif word in {'香港', '台湾', '台灣', '俄罗斯', '俄羅斯'}:
        value = 0.47
    elif word in {'省', '中文', '亚洲', '亞洲', '人民'}:
        value = 0.28
    elif word in {'中华', '中華'}:
        value = 0.55
    elif '中华民族' in word or '中華民族' in word:
        value = 1.05
    elif word in {'국', '한국', '중국', '국내'}:
        value = 0.58
    return float(value)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    position = carry[1] + 1 if carry and carry[0] == document else 0
    token = prefix.token_strings[-1]
    value = lexical_response(token)
    # Dialogue boundaries have their own response, strongest near a document start.
    inverse_root = 1.0 / math.sqrt(position + 1)
    log_position = math.log1p(position)
    if token == '<|im_start|>':
        value = -0.18 * inverse_root + 0.004 * log_position
        if position == 0:
            value = -0.209
    elif token == '<|im_end|>':
        value = 0.026 - 0.087 * inverse_root
    elif token == '<|endoftext|>':
        value = 0.025 + 0.055 * inverse_root
    elif token == '<think>':
        value = -0.18 + 0.013 * log_position - 0.04 * inverse_root
    elif token == '</think>':
        value = 0.214 + 0.003 * log_position - 0.284 * inverse_root
    return (document, position), float(value)

"""Detect indentation fragments and the beginning of a document.

The strongest positive responses are a three-space token, a lone tab, and
one space immediately after a newline. Smaller signed corrections cover
other whitespace shapes. Document-initial responses use character class,
case, and leading spaces; otherwise the prediction is near zero. This
captures the whitespace/boundary pattern, not word-specific variation.
"""
import math

READS = ()


def initial_value(s):
    word = s.strip()
    if s == '   ':
        return 0.74
    if s == '\t':
        return 0.99
    if s == '  ':
        return -0.23
    if not word:
        if s == '\xa0':
            return 0.57
        if '\n' in s:
            return 0.04 + 0.11 * min(s.count('\n') - 1, 2)
        return 0.03 if s == ' ' else 0.25
    if s.startswith('<|') or s.startswith('<tool'):
        return 0.44 if s == '<|endoftext|>' else 0.0
    if '\ufffd' in s:
        return 0.39
    if word == '#':
        return 0.065
    if s in (',', '.', '-'):
        return -0.18
    if word.isdecimal():
        return 0.0 if int(word) == 0 else 0.20
    if word.isalpha():
        if not word.isascii():
            return 0.30
        if s.startswith(' '):
            if len(word) == 1:
                return 0.03 if word.islower() else 0.16
            return 0.26 if word[0].islower() else 0.33
        if word[0].isupper():
            return 0.02 if len(word) == 1 else 0.11
        return 0.28
    return 0.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        return (doc, s, 0), initial_value(s)
    _, previous, position = carry
    position += 1
    newline = previous.endswith('\n')
    if s == '   ':
        value = 0.62
        if previous == 'n' or previous.endswith('\\n'):
            value = 0.55
        elif previous.isdecimal():
            value = 0.53
        elif newline and previous.rstrip().endswith(':'):
            value = 0.71
        elif newline and previous.rstrip().endswith(('{', '(')):
            value = 0.67
        value += 0.17 * math.exp(-position / 65.0)
    elif s == '\t':
        if previous.isdecimal():
            value = 0.49
        elif previous == '\t':
            value = 0.89
        elif previous and set(previous) == {'\t'}:
            value = 0.79
        else:
            value = 0.78 if newline else 0.67
    elif s == ' ' and newline:
        value = 0.60
    elif s == '  ':
        value = 0.02 if newline else -0.14
    elif s == '\xa0':
        value = 0.34 if previous and not previous.strip('\xa0') else 0.05
    elif s == '\xa0' * 3:
        value = 0.25
    elif s and not s.strip('\t'):
        value = max(-0.12, 0.11 - 0.036 * len(s))
    elif s and not s.strip(' '):
        spaces = len(s)
        if spaces in (6, 8):
            value = -0.16
        elif 9 <= spaces <= 12:
            value = -0.07
        else:
            value = 0.04 if spaces == 4 else 0.0
    elif s.startswith('\t') and not s[1:].strip(' '):
        spaces = len(s) - 1
        if 4 <= spaces <= 7:
            value = -0.22 if spaces <= 5 else -0.14
        else:
            value = -0.06 if spaces == 3 else 0.0
    else:
        value = 0.002 + 0.06 * math.exp(-position / 1.6)
    return (doc, s, position), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:1405 -- an "indentation token" detector.

This component is one direction written into the residual stream by layer 0's MLP. It
switches on for the whitespace token that indents a line of code, and stays off for
almost everything else (words, punctuation, digits, newlines).

Concretely, it responds to:
  * a TAB token ("\\t"), strongest when it begins a line (after a newline): about 0.75;
  * a run of THREE spaces ("   "), the usual 3-space indent token: about 0.65;
  * a single SPACE token that begins a line (right after a newline): about 0.6.
Other indentation widths (2, 4, 6, 8 spaces) do not fire, and a lone space in the middle
of prose does not fire either.

The program only looks at the current token and the one before it. It has no memory.
"""

READS = ()

# Typical activation for each indentation token, from measurements on training text.
TAB = 0.75          # "\t"
THREE_SPACES = 0.65 # "   "
LINE_SPACE = 0.6    # " " at the start of a line


def _starts_line(prefix):
    """True if the current token is the first token of a line (or of the row)."""
    if len(prefix.token_ids) < 2:
        return True
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return True
    return prefix.token_strings[-2].endswith(("\n", "\r"))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "\t":
        value = TAB
    elif token == "   ":
        value = THREE_SPACES
    elif token == " " and _starts_line(prefix):
        value = LINE_SPACE
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Recognize common code indentation: tabs, a three-space token, and a
single space at the start of a line. Other document-opening tokens receive
a small positive baseline response.
"""
READS = ()


def step(carry, prefix, upstream):
    document_before, line_start = carry or (None, True)
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if document != document_before:
        line_start = True

    if token == "\t":
        value = 0.72
    elif token == "   ":
        value = 0.65
    elif token == " " and line_start:
        value = 0.15
    elif document != document_before:
        value = 0.18
    else:
        value = 0.0

    if "\n" in token:
        line_start = not token.rsplit("\n", 1)[-1].strip()
    elif not token.isspace():
        line_start = False
    return (document, line_start), value

programs.sol:
"""A negative phrase-completion signal, strongest for 'let me' and 'let’s'.

'Let us' and other objects after 'let' respond more weakly, as do requests
with 'allow' or 'lets'. Unspaced lowercase 'let' has weaker amplitudes.
Checks, control instructions, and TODO-style reminders beginning a code
comment are additional negative triggers. Everything else is predicted zero.
Only the previous token is remembered, resetting at document boundaries.
"""
READS = ()
OTHER_ARGUMENTS = {'you', 'him', 'her', 'it', 'them', 'my', 'your', 'our', 'their', 'its'}
REMINDERS = {'TODO', 'FIXME', 'HACK', 'XXX'}
CHECKS = {'if', 'when', 'since', 'because', 'for', 'note', 'check',
          'ensure', 'verify', 'should', 'need'}
COMMENT_CONTROL = {'avoid', 'skip', 'ignore', 'prevent', 'force', 'otherwise'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    word, prior = token.strip().lower(), previous.strip().lower()
    value = 0.0
    if prior in {'let', 'lets'}:
        if word == 'me':
            value = -0.77 if previous in {'let', 'lets', ' lets'} else -1.06
        elif word in ("'s", '’s', '´s'):
            value = -0.55 if previous == 'let' else -1.04
        elif word == 'us':
            value = -0.48 if prior == 'lets' else -0.80
        elif word in OTHER_ARGUMENTS | {'this', 'the', 's'}:
            value = -0.22
    elif prior in {'allow', 'allows'}:
        if word == 'me':
            value = -0.35
        elif word == 'us':
            value = -0.14
    elif previous.strip() in {'#', '//', '/*'}:
        if token.strip() in REMINDERS:
            value = -0.54
        elif word in {'we', 'since'}:
            value = -0.34
        elif word in COMMENT_CONTROL:
            value = -0.48
        elif word in CHECKS:
            value = -0.24
    return (doc, token), value

