"""Predict the negative pulse on common “let me” and “let's” phrases."""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    recent = (previous + prefix.token_strings[-1])[-12:]
    ending = recent.lower()

    if ending.endswith("let me"):
        value = -1.06
    elif ending.endswith(("let's", "let’s")):
        value = -1.08
    elif ending.endswith("let us"):
        value = -0.81
    else:
        value = 0.0

    return (doc, recent), value

programs.sol:
"""Approximate the component's comment and heading punctuation peaks.

Hash markers, double slashes and documentation-comment asterisks receive the
largest predictions. Their strength depends on line margins, paragraph breaks,
repeated comments, numbered source listings and the most recent nonempty line.
URL scheme punctuation is excluded. Chat-header newlines have separate values,
weaker near the start of a document. Ordinary word-specific fluctuations are
left at zero. All fitted numbers describe these recognizable text classes;
there is no vocabulary-ID lookup. Short text buffers reset between documents.
"""
import re

READS: tuple[str, ...] = ()
INITIAL_MARKERS = {
    '#': -0.153, ' #': -0.503, '##': 0.278, '###': -0.155,
    '//': 0.573, ' //': 0.047, ' *': -0.054,
    '--': 0.251, ' --': -0.030,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 0, False, '')
    _, line, previous_line, previous_token, position, in_block, recent_line = carry
    token = prefix.token_strings[-1]
    text = token.replace('\\n', '\n').replace('\\r', '\r').replace('\\t', '\t')
    numbered = bool(re.search(r'\d+\t', line))
    margin = re.sub(r'^\s*[+-]?\s*\d+\t', '', line)
    margin = re.sub(r'^\s*[+-]', '', margin)
    at_margin = not margin.strip()
    previous_comment = previous_line.lstrip().startswith(('#', '//', '*', '/*'))
    blank_break = previous_token.endswith(('\n\n', '\\n\\n'))
    prior_code = any(c in recent_line for c in '{}();=')
    prior_fence = '```' in recent_line
    value = 0.0
    stripped = token.strip()
    if '//' in token and '://' not in token:
        if '\n' in token:
            value = 0.22 if previous_comment else 0.31
        elif token.count('/') >= 3:
            value = 0.60
        else:
            if at_margin:
                value = (0.78 - 0.13 * previous_comment
                         - 0.05 * token.startswith(' ')
                         + 0.40 * blank_break + 0.13 * prior_code
                         + 0.32 * prior_fence)
            else:
                operand = line.rstrip()[-1:].isalnum()
                inside_parens = line.count('(') > line.count(')')
                value = 0.72
                if operand:
                    value = 0.34 if inside_parens else 0.45
        if numbered:
            value -= 0.15
    elif '#' in token:
        if stripped and set(stripped) == {'#'}:
            n = len(stripped)
            if n == 1:
                if at_margin:
                    value = (1.06 - 0.26 * previous_comment - 0.22 * numbered
                             + 0.18 * blank_break + 0.13 * prior_code
                             + 0.34 * prior_fence)
                elif line and line[-1].isspace():
                    value = 1.0
                elif (token.startswith(' ')
                      and line.rstrip().endswith((')', ']', '}'))):
                    value = 1.0
                else:
                    value = 0.36 if token.startswith(' ') else 0.62
            elif n == 2:
                value = (0.56 - 0.30 * previous_comment + 0.08 * blank_break
                             + 0.40 * prior_fence) if at_margin else 0.16
            else:
                # Markdown heading levels versus decorative hash rules.
                strength = 0.38 if n <= 4 else 0.20 if n <= 6 else 0.45
                value = strength if at_margin else 0.05
                if at_margin:
                    value += 0.30 * prior_fence
            if '\n' in token:
                value = 0.40 if n == 1 else 0.15
        elif stripped in ('#include', '#define', '#ifdef', '#ifndef'):
            value = 0.12
        elif stripped == '#endif':
            value = 0.86
        elif '&#' in token:
            value = 0.27
        else:
            value = 0.48
    elif token.startswith(' *') and not token.startswith(' **'):
        if at_margin:
            if '\n' in token:
                value = 0.42 if numbered else 0.58
            elif numbered:
                value = 0.77
            elif previous_line.lstrip().startswith('/*'):
                value = 1.65
            elif in_block or previous_line.lstrip().startswith('*'):
                value = 1.10
            else:
                value = 0.48
        else:
            value = 0.13 if line and line[-1].isspace() else 0.0
    elif stripped == '--':
        value = (0.48 if not line else 0.23) if at_margin else 0.02
        if '\n' in token:
            value = 0.12
    elif token == '\n' and line.endswith('<|im_start|>user'):
        value = 0.108 if position == 2 else (0.22 if position < 10 else 0.477)
    elif token == '\n' and line.endswith('<|im_start|>assistant') and position < 10:
        value = -0.225 if position == 2 else -0.10
    if position == 0:
        value = INITIAL_MARKERS.get(token, 0.0)
    if '/*' in text or '*/' in text:
        in_block = text.rfind('/*') > text.rfind('*/')
    parts = text.split('\n')
    if len(parts) > 1:
        for completed in [line + parts[0]] + parts[1:-1]:
            if completed.strip():
                recent_line = completed[-256:]
        previous_line = (line + parts[0])[-256:] if len(parts) == 2 else parts[-2][-256:]
        line = parts[-1][-256:]
    else:
        line = (line + text)[-256:]
    state = (doc, line, previous_line, token, position + 1, in_block, recent_line)
    return state, float(value)

programs.haiku:
"""Comment and heading openers.

The component fires on the token that opens a comment or a markdown heading:
`#` (Python, shell), `//` and `///` (C-style), `--` (SQL, Lua), and the leading
` *` of a javadoc line. It is strongest when that token starts a line, and weaker
when it sits after code on the same line (where `#` or `//` is less often a comment).
It also gives a weak response to the newline that opens a chat user turn.
"""

READS = ()

# Tokens that open a comment, at line start and mid-line.
COMMENT_OPENERS = {"#", " #", "//", " //", "//#", " //#", "#[", " #["}
# Comment openers that are only comments at the start of a line.
LINE_COMMENT_OPENERS = {"--"}
# Triple-slash doc comments.
DOC_OPENERS = {"///", " ///", "///\n"}
# Markdown heading markers.
HEADING_MARKS = {"##", "###", "####", " ##"}
# Javadoc continuation lines, ` * text`.
JAVADOC_MARK = " *"


def starts_line(prefix):
    """True if only whitespace separates this token from the start of its line."""
    for s in reversed(prefix.token_strings[:-1]):
        if "\n" in s:
            return True
        if s.strip():
            return False
    return True


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    strings = prefix.token_strings
    line_start = starts_line(prefix)
    if token in COMMENT_OPENERS:
        value = 1.05 if line_start else 0.7
    elif token in DOC_OPENERS:
        value = 0.6 if line_start else 0.3
    elif token in LINE_COMMENT_OPENERS:
        value = 0.45 if line_start else 0.0
    elif token == JAVADOC_MARK:
        value = 1.2 if line_start else 0.13
    elif token in HEADING_MARKS:
        value = 0.5 if line_start else 0.2
    elif token == "\n" and len(strings) >= 3 and strings[-2] == "user" and strings[-3] == "<|im_start|>":
        value = 0.35
    else:
        value = 0.0
    return carry, float(value)
